{
  "name": "LO Academie",
  "description": "De gezamenlijke scholingskalender van ALO Nederland en de KVLO."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Organizer {
  KVLO = 'KVLO',
  ALO = 'ALO Nederland',
  JOINT = 'Gezamenlijk'
}

export interface Course {
  id: string;
  title: string;
  organizer: Organizer;
  date: string; // ISO date string
  location: string;
  region: string;
  price: number;
  description: string;
  tags: string[];
  url: string;
  imageUrl?: string;
}

export interface SearchFilters {
  query: string;
  region: string;
  dateStart: string;
  organizer: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import { GoogleGenAI } from "@google/genai";
import { Course } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getSmartRecommendations = async (userQuery: string, availableCourses: Course[]): Promise<string> => {
  try {
    const courseContext = JSON.stringify(availableCourses.map(c => ({
      id: c.id,
      title: c.title,
      date: c.date,
      organizer: c.organizer,
      region: c.region,
      description: c.description
    })));

    const prompt = `
      Je bent een behulpzame assistent voor 'LO Academie', de scholingskalender van KVLO en ALO Nederland.

      Hier is de lijst met beschikbare cursussen in JSON formaat:
      ${courseContext}

      De gebruiker vraagt: "${userQuery}"

      Antwoord in het Nederlands. Wees vriendelijk en professioneel.
      Beveel 1 tot 3 relevante cursussen aan op basis van de vraag.
      Als je specifieke cursussen aanbeveelt, noem dan duidelijk de titel en de datum.
      Als er geen perfecte match is, doe een suggestie die in de buurt komt of vraag om verduidelijking.
      Houd het antwoord beknopt (max 100 woorden).
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Sorry, ik kon op dit moment geen antwoord genereren.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Er is een fout opgetreden bij het ophalen van slimme aanbevelingen. Probeer de gewone zoekfilters.";
  }
};

import React from 'react';
import { Course, Organizer } from '../types';
import { MapPin, Calendar, Tag, ArrowRight } from 'lucide-react';

interface CourseCardProps {
  course: Course;
}

export const CourseCard: React.FC<CourseCardProps> = ({ course }) => {
  const isKVLO = course.organizer === Organizer.KVLO;
  const isALO = course.organizer === Organizer.ALO;

  const badgeColor = isKVLO 
    ? 'bg-orange-100 text-orange-800 border-orange-200' 
    : isALO 
      ? 'bg-cyan-100 text-cyan-800 border-cyan-200'
      : 'bg-purple-100 text-purple-800 border-purple-200';

  return (
    <div className="group bg-white rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all duration-300 flex flex-col h-full overflow-hidden">
      <div className="relative h-48 overflow-hidden">
        <img 
          src={course.imageUrl} 
          alt={course.title} 
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
        />
        <div className="absolute top-3 right-3">
            <span className={`px-3 py-1 rounded-full text-xs font-bold border ${badgeColor}`}>
                {course.organizer}
            </span>
        </div>
      </div>

      <div className="p-5 flex-1 flex flex-col">
        <div className="flex justify-between items-start mb-2">
            <div className="flex gap-2 text-xs font-medium text-slate-500">
                <span className="flex items-center gap-1">
                    <Calendar className="w-3 h-3" />
                    {new Date(course.date).toLocaleDateString('nl-NL', { day: 'numeric', month: 'short', year: 'numeric' })}
                </span>
                <span>•</span>
                <span className="flex items-center gap-1">
                    <MapPin className="w-3 h-3" />
                    {course.location}
                </span>
            </div>
        </div>

        <h3 className="text-xl font-bold text-slate-800 mb-2 leading-tight group-hover:text-[#004890] transition-colors">
          {course.title}
        </h3>

        <p className="text-slate-600 text-sm mb-4 line-clamp-3 flex-1">
          {course.description}
        </p>

        <div className="flex flex-wrap gap-2 mb-4">
            {course.tags.map(tag => (
                <span key={tag} className="flex items-center gap-1 text-xs bg-slate-100 text-slate-600 px-2 py-1 rounded-md">
                    <Tag className="w-3 h-3" /> {tag}
                </span>
            ))}
        </div>

        <div className="mt-auto pt-4 border-t border-slate-100 flex items-center justify-between">
            <span className="font-bold text-lg text-slate-900">€{course.price},-</span>
            <a 
                href={course.url} 
                target="_blank" 
                rel="noreferrer"
                className="inline-flex items-center gap-1 text-sm font-semibold text-[#007da5] hover:text-[#004890] transition-colors"
            >
                Info & Aanmelden <ArrowRight className="w-4 h-4" />
            </a>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Course, Organizer } from '../types';
import { REGIONS } from '../constants';
import { X } from 'lucide-react';

interface AddCourseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (course: Course) => void;
}

export const AddCourseModal: React.FC<AddCourseModalProps> = ({ isOpen, onClose, onAdd }) => {
  const [formData, setFormData] = useState<Partial<Course>>({
    organizer: Organizer.KVLO,
    region: 'Landelijk',
    price: 0,
    tags: []
  });
  const [tagInput, setTagInput] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.date || !formData.description) return;

    const newCourse: Course = {
      id: Date.now().toString(),
      title: formData.title,
      organizer: formData.organizer as Organizer,
      date: formData.date,
      location: formData.location || 'Onbekend',
      region: formData.region || 'Landelijk',
      price: Number(formData.price) || 0,
      description: formData.description,
      tags: formData.tags || [],
      url: '#',
      imageUrl: `https://picsum.photos/seed/${Date.now()}/400/300`
    };

    onAdd(newCourse);
    onClose();
  };

  const handleAddTag = () => {
    if (tagInput.trim()) {
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), tagInput.trim()]
      }));
      setTagInput('');
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center sticky top-0 bg-white z-10">
          <h2 className="text-2xl font-bold text-slate-800">Nieuwe Bijscholing Toevoegen</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <X className="w-6 h-6 text-slate-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-700">Titel</label>
              <input 
                required
                type="text" 
                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] focus:border-transparent outline-none"
                value={formData.title || ''}
                onChange={e => setFormData({...formData, title: e.target.value})}
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-700">Organisator</label>
              <select 
                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none"
                value={formData.organizer}
                onChange={e => setFormData({...formData, organizer: e.target.value as Organizer})}
              >
                {Object.values(Organizer).map(org => (
                  <option key={org} value={org}>{org}</option>
                ))}
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-700">Datum</label>
              <input 
                required
                type="date" 
                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none"
                value={formData.date || ''}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />
            </div>

            <div className="space-y-2">
               <label className="text-sm font-semibold text-slate-700">Locatie</label>
               <input 
                 type="text"
                 className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none"
                 value={formData.location || ''}
                 onChange={e => setFormData({...formData, location: e.target.value})}
               />
            </div>

            <div className="space-y-2">
               <label className="text-sm font-semibold text-slate-700">Regio</label>
               <select 
                 className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none"
                 value={formData.region}
                 onChange={e => setFormData({...formData, region: e.target.value})}
               >
                 {REGIONS.map(r => <option key={r} value={r}>{r}</option>)}
               </select>
            </div>

            <div className="space-y-2">
               <label className="text-sm font-semibold text-slate-700">Prijs (€)</label>
               <input 
                 type="number"
                 className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none"
                 value={formData.price}
                 onChange={e => setFormData({...formData, price: Number(e.target.value)})}
               />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Omschrijving</label>
            <textarea 
              required
              rows={4}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none resize-none"
              value={formData.description || ''}
              onChange={e => setFormData({...formData, description: e.target.value})}
            />
          </div>

          <div className="space-y-2">
             <label className="text-sm font-semibold text-slate-700">Tags</label>
             <div className="flex gap-2">
               <input 
                 type="text" 
                 className="flex-1 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none"
                 placeholder="Bijv: PO, Motorisch Leren..."
                 value={tagInput}
                 onChange={e => setTagInput(e.target.value)}
                 onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), handleAddTag())}
               />
               <button 
                 type="button" 
                 onClick={handleAddTag}
                 className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors"
               >
                 +
               </button>
             </div>
             <div className="flex flex-wrap gap-2 mt-2">
               {formData.tags?.map(tag => (
                 <span key={tag} className="bg-[#004890]/10 text-[#004890] px-2 py-1 rounded text-sm flex items-center gap-1">
                   {tag}
                   <button 
                     type="button"
                     onClick={() => setFormData({...formData, tags: formData.tags?.filter(t => t !== tag)})}
                     className="hover:text-red-500"
                   >
                     ×
                   </button>
                 </span>
               ))}
             </div>
          </div>

          <div className="pt-4 flex justify-end gap-3">
            <button 
              type="button" 
              onClick={onClose}
              className="px-6 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
            >
              Annuleren
            </button>
            <button 
              type="submit"
              className="px-6 py-2 bg-gradient-to-r from-[#004890] to-[#007da5] text-white font-bold rounded-lg hover:shadow-lg transition-shadow"
            >
              Toevoegen
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Course, ChatMessage } from '../types';
import { getSmartRecommendations } from '../services/geminiService';
import { Sparkles, Send, X, Bot } from 'lucide-react';

interface AIAssistantProps {
  courses: Course[];
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ courses }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hoi! Ik ben de slimme assistent van LO Academie. Waar ben je naar op zoek?' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userText = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userText }]);
    setLoading(true);

    const response = await getSmartRecommendations(userText, courses);

    setMessages(prev => [...prev, { role: 'model', text: response }]);
    setLoading(false);
  };

  return (
    <>
      {/* Floating Action Button */}
      <button 
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-40 p-4 rounded-full shadow-xl transition-all duration-300 flex items-center gap-2
          ${isOpen ? 'scale-0 opacity-0' : 'scale-100 opacity-100'}
          bg-gradient-to-r from-[#f39200] to-[#e65c00] text-white hover:scale-110`}
      >
        <Sparkles className="w-6 h-6" />
        <span className="font-bold hidden md:inline">Slimme Zoekhulp</span>
      </button>

      {/* Chat Interface */}
      <div className={`fixed bottom-6 right-6 z-50 w-full md:w-[400px] h-[500px] bg-white rounded-2xl shadow-2xl border border-slate-200 flex flex-col transition-all duration-300 transform origin-bottom-right
        ${isOpen ? 'scale-100 opacity-100' : 'scale-0 opacity-0 pointer-events-none'}`}>

        {/* Chat Header */}
        <div className="p-4 bg-gradient-to-r from-[#004890] to-[#007da5] rounded-t-2xl flex justify-between items-center text-white">
          <div className="flex items-center gap-2">
            <Bot className="w-6 h-6" />
            <h3 className="font-bold">LO Academie Assistent</h3>
          </div>
          <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1 rounded-full transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                msg.role === 'user' 
                  ? 'bg-[#007da5] text-white rounded-tr-none' 
                  : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none shadow-sm'
              }`}>
                {msg.text}
              </div>
            </div>
          ))}
          {loading && (
             <div className="flex justify-start">
               <div className="bg-white border border-slate-200 p-3 rounded-2xl rounded-tl-none shadow-sm flex gap-1">
                 <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                 <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                 <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-150"></div>
               </div>
             </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="p-3 bg-white border-t border-slate-100">
          <div className="flex gap-2">
            <input 
              type="text" 
              className="flex-1 px-4 py-2 border border-slate-300 rounded-full focus:outline-none focus:ring-2 focus:ring-[#007da5]"
              placeholder="Typ je vraag..."
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
            />
            <button 
              onClick={handleSend}
              disabled={loading || !input.trim()}
              className="p-2 bg-[#004890] text-white rounded-full hover:bg-[#00366d] disabled:opacity-50 transition-colors"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useMemo } from 'react';
import { Header } from './components/Header';
import { CourseCard } from './components/CourseCard';
import { AddCourseModal } from './components/AddCourseModal';
import { AIAssistant } from './components/AIAssistant';
import { Course, SearchFilters } from './types';
import { INITIAL_COURSES, REGIONS } from './constants';
import { Search, PlusCircle, Filter } from 'lucide-react';

const App: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>(INITIAL_COURSES);
  const [filters, setFilters] = useState<SearchFilters>({
    query: '',
    region: 'Alle',
    dateStart: '',
    organizer: 'Alle'
  });
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filter Logic
  const filteredCourses = useMemo(() => {
    return courses.filter(course => {
      const matchesQuery = 
        course.title.toLowerCase().includes(filters.query.toLowerCase()) || 
        course.description.toLowerCase().includes(filters.query.toLowerCase()) ||
        course.tags.some(tag => tag.toLowerCase().includes(filters.query.toLowerCase()));

      const matchesRegion = filters.region === 'Alle' || course.region === filters.region;

      const matchesDate = !filters.dateStart || new Date(course.date) >= new Date(filters.dateStart);

      const matchesOrganizer = filters.organizer === 'Alle' || course.organizer === filters.organizer;

      return matchesQuery && matchesRegion && matchesDate && matchesOrganizer;
    });
  }, [courses, filters]);

  const handleAddCourse = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header />

      <main className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Hero / Intro Section */}
        <div className="mb-10 text-center space-y-4">
          <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 tracking-tight">
            Ontwikkel jezelf met <br className="hidden md:block" />
            <span className="text-[#004890]">KVLO</span> & <span className="text-[#007da5]">ALO Nederland</span>
          </h1>
          <p className="text-lg text-slate-600 max-w-2xl mx-auto">
            Het complete overzicht van bijscholingen voor bewegingsonderwijs. 
            Van vakwerkplan tot motorisch leren.
          </p>
        </div>

        {/* Search & Filter Bar */}
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-8 sticky top-24 z-30">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">

            {/* Search Text */}
            <div className="relative md:col-span-1 lg:col-span-2">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
              <input 
                type="text" 
                placeholder="Zoek op onderwerp, inhoud..." 
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] focus:border-transparent outline-none transition-all"
                value={filters.query}
                onChange={e => setFilters({...filters, query: e.target.value})}
              />
            </div>

            {/* Region Select */}
            <div className="relative">
              <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
              <select 
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none appearance-none bg-white"
                value={filters.region}
                onChange={e => setFilters({...filters, region: e.target.value})}
              >
                <option value="Alle">Alle Regio's</option>
                {REGIONS.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>

             {/* Organizer Select */}
             <div className="relative">
              <select 
                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none appearance-none bg-white"
                value={filters.organizer}
                onChange={e => setFilters({...filters, organizer: e.target.value})}
              >
                <option value="Alle">Alle Organisatoren</option>
                <option value="KVLO">KVLO</option>
                <option value="ALO Nederland">ALO Nederland</option>
                <option value="Gezamenlijk">Gezamenlijk</option>
              </select>
            </div>

          </div>

          <div className="mt-4 flex flex-col sm:flex-row justify-between items-center border-t border-slate-100 pt-4 gap-4">
              <div className="text-sm text-slate-500 font-medium">
                  {filteredCourses.length} bijscholingen gevonden
              </div>
              <button 
                  onClick={() => setIsModalOpen(true)}
                  className="flex items-center gap-2 px-4 py-2 bg-[#f39200] text-white rounded-lg font-bold hover:bg-[#d68100] transition-colors shadow-md hover:shadow-lg w-full sm:w-auto justify-center"
              >
                  <PlusCircle className="w-5 h-5" />
                  Nieuwe toevoegen (Admin)
              </button>
          </div>
        </div>

        {/* Results Grid */}
        {filteredCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredCourses.map(course => (
              <CourseCard key={course.id} course={course} />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-slate-300">
            <h3 className="text-xl font-bold text-slate-700">Geen bijscholingen gevonden</h3>
            <p className="text-slate-500">Pas je filters aan of gebruik de slimme zoekhulp.</p>
          </div>
        )}

      </main>

      <footer className="bg-slate-900 text-slate-400 py-12">
          <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 md:grid-cols-3 gap-8">
              <div>
                  <h4 className="text-white font-bold text-lg mb-4">Over LO Academie</h4>
                  <p className="text-sm leading-relaxed">
                      LO Academie is een initiatief van KVLO en ALO Nederland om het scholingsaanbod voor bewegingsonderwijs te centraliseren en toegankelijk te maken voor iedere professional.
                  </p>
              </div>
              <div>
                   <h4 className="text-white font-bold text-lg mb-4">Snelle Links</h4>
                   <ul className="space-y-2 text-sm">
