import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { CourseCard } from './components/CourseCard';
import { AddCourseModal } from './components/AddCourseModal';
import { AIAssistant } from './components/AIAssistant';
import { Course, SearchFilters } from './types';
import { INITIAL_COURSES, REGIONS } from './constants';
import { Search, PlusCircle, Filter, Calendar, ChevronDown, Check, X } from 'lucide-react';

const App: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>(INITIAL_COURSES);
  const [filters, setFilters] = useState<SearchFilters>({
    query: '',
    region: 'Alle',
    dateStart: '',
    dateEnd: '',
    organizer: 'Alle',
    selectedTags: []
  });
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTagDropdownOpen, setIsTagDropdownOpen] = useState(false);
  const tagDropdownRef = useRef<HTMLDivElement>(null);

  // Close tag dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (tagDropdownRef.current && !tagDropdownRef.current.contains(event.target as Node)) {
        setIsTagDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Calculate unique tags
  const uniqueTags = useMemo(() => {
    const tags = new Set<string>();
    courses.forEach(course => course.tags.forEach(tag => tags.add(tag)));
    return Array.from(tags).sort();
  }, [courses]);

  // Filter Logic
  const filteredCourses = useMemo(() => {
    return courses.filter(course => {
      const matchesQuery = 
        course.title.toLowerCase().includes(filters.query.toLowerCase()) || 
        course.description.toLowerCase().includes(filters.query.toLowerCase()) ||
        course.tags.some(tag => tag.toLowerCase().includes(filters.query.toLowerCase()));

      const matchesRegion = filters.region === 'Alle' || course.region === filters.region;

      const courseDate = new Date(course.date);
      const matchesDateStart = !filters.dateStart || courseDate >= new Date(filters.dateStart);
      const matchesDateEnd = !filters.dateEnd || courseDate <= new Date(filters.dateEnd);

      const matchesOrganizer = filters.organizer === 'Alle' || course.organizer === filters.organizer;

      const matchesTags = filters.selectedTags.length === 0 || 
        filters.selectedTags.some(tag => course.tags.includes(tag));

      return matchesQuery && matchesRegion && matchesDateStart && matchesDateEnd && matchesOrganizer && matchesTags;
    });
  }, [courses, filters]);

  const handleAddCourse = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
  };

  const toggleTag = (tag: string) => {
    setFilters(prev => {
      const newTags = prev.selectedTags.includes(tag)
        ? prev.selectedTags.filter(t => t !== tag)
        : [...prev.selectedTags, tag];
      return { ...prev, selectedTags: newTags };
    });
  };

  const clearTags = () => {
    setFilters(prev => ({ ...prev, selectedTags: [] }));
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header />

      <main className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Hero / Intro Section */}
        <div className="mb-10 text-center space-y-4">
          <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 tracking-tight">
            Ontwikkel jezelf met <br className="hidden md:block" />
            <span className="text-[#004890]">KVLO</span> & <span className="text-[#007da5]">ALO Nederland</span>
          </h1>
          <p className="text-lg text-slate-600 max-w-2xl mx-auto">
            Het complete overzicht van bijscholingen voor bewegingsonderwijs. 
            Van vakwerkplan tot motorisch leren.
          </p>
        </div>

        {/* Search & Filter Bar */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-8 sticky top-24 z-30">
          <div className="space-y-4">

            {/* Top Row: Text Search & Add Button */}
            <div className="flex flex-col md:flex-row gap-4">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Zoek op titel, onderwerp of trefwoord..." 
                  className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] focus:border-transparent outline-none transition-all shadow-sm"
                  value={filters.query}
                  onChange={e => setFilters({...filters, query: e.target.value})}
                />
              </div>
              <button 
                onClick={() => setIsModalOpen(true)}
                className="flex items-center gap-2 px-6 py-3 bg-[#f39200] text-white rounded-lg font-bold hover:bg-[#d68100] transition-colors shadow-md hover:shadow-lg whitespace-nowrap justify-center"
              >
                <PlusCircle className="w-5 h-5" />
                Toevoegen
              </button>
            </div>

            {/* Middle Row: Filters Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">

              {/* Date Range Picker */}
              <div className="sm:col-span-2 flex gap-2 items-center bg-slate-50 p-1 rounded-lg border border-slate-200">
                <div className="relative flex-1">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <span className="text-xs text-slate-400">Van</span>
                    </div>
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-2 py-2 bg-transparent text-sm focus:outline-none text-slate-700"
                      value={filters.dateStart}
                      onChange={e => setFilters({...filters, dateStart: e.target.value})}
                    />
                </div>
                <div className="w-px h-6 bg-slate-300"></div>
                <div className="relative flex-1">
                     <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <span className="text-xs text-slate-400">Tot</span>
                    </div>
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-2 py-2 bg-transparent text-sm focus:outline-none text-slate-700"
                      value={filters.dateEnd}
                      onChange={e => setFilters({...filters, dateEnd: e.target.value})}
                    />
                </div>
              </div>

              {/* Region Select */}
              <div className="relative">
                <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                <select 
                  className="w-full pl-10 pr-8 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none appearance-none bg-white text-sm"
                  value={filters.region}
                  onChange={e => setFilters({...filters, region: e.target.value})}
                >
                  <option value="Alle">Alle Regio's</option>
                  {REGIONS.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
              </div>

              {/* Organizer Select */}
              <div className="relative">
                <select 
                  className="w-full px-4 pr-8 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-[#007da5] outline-none appearance-none bg-white text-sm"
                  value={filters.organizer}
                  onChange={e => setFilters({...filters, organizer: e.target.value})}
                >
                  <option value="Alle">Alle Organisatoren</option>
                  <option value="KVLO">KVLO</option>
                  <option value="ALO Nederland">ALO Nederland</option>
                  <option value="Gezamenlijk">Gezamenlijk</option>
                </select>
                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
              </div>
            </div>

            {/* Bottom Row: Tags Dropdown */}
            <div className="relative" ref={tagDropdownRef}>
              <button 
                onClick={() => setIsTagDropdownOpen(!isTagDropdownOpen)}
                className={`w-full md:w-auto min-w-[200px] flex items-center justify-between gap-3 px-4 py-2.5 border rounded-lg text-sm font-medium transition-all ${
                  isTagDropdownOpen || filters.selectedTags.length > 0
                    ? 'border-[#007da5] text-[#007da5] bg-sky-50' 
                    : 'border-slate-300 text-slate-600 hover:border-slate-400'
                }`}
              >
                <div className="flex items-center gap-2">
                   <Filter className="w-4 h-4" />
                   <span>
                     {filters.selectedTags.length === 0 
                       ? 'Filter op Tags' 
                       : `${filters.selectedTags.length} tag${filters.selectedTags.length > 1 ? 's' : ''} geselecteerd`}
                   </span>
                </div>
                <ChevronDown className={`w-4 h-4 transition-transform ${isTagDropdownOpen ? 'rotate-180' : ''}`} />
              </button>

              {/* Tag Dropdown Panel */}
              {isTagDropdownOpen && (
                <div className="absolute top-full left-0 mt-2 w-full md:w-[400px] bg-white rounded-xl shadow-xl border border-slate-200 p-4 z-50 animate-in fade-in slide-in-from-top-2">
                  <div className="flex justify-between items-center mb-3 pb-2 border-b border-slate-100">
                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Beschikbare Tags</span>
                    {filters.selectedTags.length > 0 && (
                      <button onClick={clearTags} className="text-xs text-red-500 hover:text-red-600 font-medium">
                        Wis alles
                      </button>
                    )}
                  </div>
                  <div className="flex flex-wrap gap-2 max-h-[200px] overflow-y-auto custom-scrollbar">
                    {uniqueTags.map(tag => {
                      const isSelected = filters.selectedTags.includes(tag);
                      return (
                        <button
                          key={tag}
                          onClick={() => toggleTag(tag)}
                          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                            isSelected 
                              ? 'bg-[#007da5] text-white' 
                              : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                          }`}
                        >
                          {tag}
                          {isSelected && <Check className="w-3 h-3" />}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>

            {/* Active Filters Display */}
            {filters.selectedTags.length > 0 && (
                <div className="flex flex-wrap gap-2 pt-2">
                    {filters.selectedTags.map(tag => (
                        <span key={tag} className="flex items-center gap-1 bg-sky-100 text-[#007da5] text-xs font-bold px-3 py-1 rounded-full animate-in zoom-in-95">
                            {tag}
                            <button onClick={() => toggleTag(tag)} className="hover:text-[#004890]">
                                <X className="w-3 h-3" />
                            </button>
                        </span>
                    ))}
                </div>
            )}

          </div>

          <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between items-center text-sm text-slate-500">
             <span>{filteredCourses.length} resultaten</span>
             {(filters.query || filters.region !== 'Alle' || filters.organizer !== 'Alle' || filters.dateStart || filters.dateEnd || filters.selectedTags.length > 0) && (
                <button 
                    onClick={() => setFilters({
                        query: '', 
                        region: 'Alle', 
                        dateStart: '', 
                        dateEnd: '', 
                        organizer: 'Alle', 
                        selectedTags: []
                    })}
                    className="text-[#004890] hover:underline"
                >
                    Filters wissen
                </button>
             )}
          </div>
        </div>

        {/* Results Grid */}
        {filteredCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredCourses.map(course => (
              <CourseCard key={course.id} course={course} />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-slate-300">
            <h3 className="text-xl font-bold text-slate-700">Geen bijscholingen gevonden</h3>
            <p className="text-slate-500">Pas je filters aan of gebruik de slimme zoekhulp.</p>
          </div>
        )}

      </main>

      <footer className="bg-slate-900 text-slate-400 py-12">
          <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 md:grid-cols-3 gap-8">
