import React, { useState, useEffect } from 'react';
import { Course, Organizer } from '../types';
import { MapPin, Calendar, Tag, ArrowRight } from 'lucide-react';
import { DEFAULT_IMAGES } from '../constants';

interface CourseCardProps {
  course: Course;
}

export const CourseCard: React.FC<CourseCardProps> = ({ course }) => {
  const [hasError, setHasError] = useState(false);
  const isKVLO = course.organizer === Organizer.KVLO;
  const isALO = course.organizer === Organizer.ALO;

  // Reset error state if the course changes
  useEffect(() => {
    setHasError(false);
  }, [course.imageUrl]);

  // Deterministic fallback based on course ID
  const fallbackIndex = course.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0) % DEFAULT_IMAGES.length;
  const fallbackImage = DEFAULT_IMAGES[fallbackIndex];

  const displayImage = !hasError && course.imageUrl ? course.imageUrl : fallbackImage;

  // Sportier badge colors
  const badgeColor = isKVLO 
    ? 'bg-[#7AB800]/10 text-[#5a8700] border-[#7AB800]/20' 
    : isALO 
      ? 'bg-[#00C1D4]/10 text-[#008d9b] border-[#00C1D4]/20'
      : 'bg-purple-100 text-purple-700 border-purple-200';

  return (
    <div className="group bg-white rounded-2xl border border-slate-100 shadow-sm hover:shadow-xl hover:shadow-slate-200/50 transition-all duration-300 flex flex-col h-full overflow-hidden hover:-translate-y-1">
      <div className="relative h-52 overflow-hidden bg-slate-200">
        <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent z-10 opacity-60"></div>
        <img 
          src={displayImage} 
          alt={course.title} 
          onError={() => setHasError(true)}
          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
        />
        <div className="absolute top-4 right-4 z-20">
            <span className={`px-3 py-1 rounded-lg text-xs font-black uppercase tracking-wider border backdrop-blur-sm bg-white/90 ${badgeColor}`}>
                {course.organizer}
            </span>
        </div>
        <div className="absolute bottom-4 left-4 z-20 flex flex-col text-white shadow-sm">
             <div className="flex items-center gap-1.5 text-xs font-bold mb-1 opacity-90">
                 <Calendar className="w-3.5 h-3.5" />
                 {new Date(course.date).toLocaleDateString('nl-NL', { day: 'numeric', month: 'short', year: 'numeric' })}
             </div>
        </div>
      </div>

      <div className="p-6 flex-1 flex flex-col">
        <div className="flex items-start justify-between mb-3">
             <div className="flex items-center gap-1.5 text-xs font-bold text-slate-400 uppercase tracking-wide">
                <MapPin className="w-3.5 h-3.5" />
                {course.location}
            </div>
        </div>

        <h3 className="text-xl font-extrabold text-slate-800 mb-3 leading-tight group-hover:text-[#00C1D4] transition-colors">
          {course.title}
        </h3>

        <p className="text-slate-600 text-sm mb-5 line-clamp-3 flex-1 leading-relaxed">
          {course.description}
        </p>

        <div className="flex flex-wrap gap-2 mb-6">
            {course.tags.slice(0, 3).map(tag => (
                <span key={tag} className="flex items-center gap-1 text-[11px] font-bold bg-slate-50 text-slate-500 px-2.5 py-1 rounded-md border border-slate-100 uppercase tracking-wide">
                    {tag}
                </span>
            ))}
        </div>

        <div className="mt-auto pt-5 border-t border-slate-50 flex items-center justify-between">
            <span className="font-black text-xl text-[#7AB800]">
                {course.price === 0 ? 'Gratis' : `€${course.price},-`}
            </span>
            <a 
                href={course.url} 
                target="_blank" 
                rel="noreferrer"
                className="inline-flex items-center gap-1.5 text-sm font-bold text-[#00C1D4] hover:text-[#0096a6] transition-colors group/link"
            >
                Info & Aanmelden <ArrowRight className="w-4 h-4 transition-transform group-hover/link:translate-x-1" />
            </a>
        </div>
      </div>
    </div>
  );
};

