                        <span key={tag} className="flex items-center gap-1 bg-[#F0FDF4] text-[#7AB800] border border-[#DCFCE7] text-xs font-bold px-3 py-1 rounded-full animate-in zoom-in-95">
                            {tag}
                            <button onClick={() => toggleTag(tag)} className="hover:text-red-500 transition-colors">
                                <X className="w-3 h-3" />
                            </button>
                        </span>
                    ))}
                </div>
            )}

          </div>

          <div className="mt-6 pt-4 border-t border-slate-100 flex justify-between items-center text-sm text-slate-500">
             <div className="flex items-center gap-6">
               <span className="font-medium">{filteredAndSortedCourses.length} scholingen gevonden</span>
               <button 
                type="button"
                onClick={handleAdminCheck}
                className="flex items-center gap-1 text-slate-400 hover:text-[#00C1D4] transition-colors text-xs hover:bg-[#F0FDFA] px-2 py-1 rounded cursor-pointer font-medium"
               >
                 <Lock className="w-3 h-3" />
                 <span>Toevoegen</span>
               </button>
             </div>

             {(filters.query || filters.region !== 'Alle' || filters.organizer !== 'Alle' || filters.dateStart || filters.dateEnd || filters.selectedTags.length > 0 || showOnlyFavorites) && (
