import React, { useState, useEffect } from 'react';
import { Course, Organizer } from '../types';
import { MapPin, Calendar, ArrowRight, Heart, Share2, Check, Eye } from 'lucide-react';
import { DEFAULT_IMAGES } from '../constants';

interface CourseCardProps {
  course: Course;
  isFavorite: boolean;
  onToggleFavorite: (id: string) => void;
  onClick: (course: Course) => void;
}

export const CourseCard: React.FC<CourseCardProps> = ({ course, isFavorite, onToggleFavorite, onClick }) => {
  const [hasError, setHasError] = useState(false);
  const [isCopied, setIsCopied] = useState(false);

  const isKVLO = course.organizer === Organizer.KVLO;
  const isALO = course.organizer === Organizer.ALO;

  useEffect(() => {
    setHasError(false);
  }, [course.imageUrl]);

  const fallbackIndex = course.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0) % DEFAULT_IMAGES.length;
  const displayImage = !hasError && course.imageUrl ? course.imageUrl : DEFAULT_IMAGES[fallbackIndex];

  const badgeColor = isKVLO 
    ? 'bg-[#7AB800]/10 text-[#5a8700] border-[#7AB800]/20' 
    : isALO 
      ? 'bg-[#00C1D4]/10 text-[#008d9b] border-[#00C1D4]/20'
      : 'bg-purple-100 text-purple-700 border-purple-200';

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent opening modal
    e.preventDefault();
    const shareData = {
      title: course.title,
      text: `Bekijk deze scholing op LO Academie: ${course.title}`,
      url: window.location.href
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(`${course.title} - ${course.url}`);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  return (
    <div 
      onClick={() => onClick(course)}
      className="group bg-white rounded-2xl border border-slate-100 shadow-sm hover:shadow-xl hover:shadow-slate-200/50 transition-all duration-300 flex flex-col h-full overflow-hidden hover:-translate-y-1 relative cursor-pointer"
    >

      {/* Actions (Heart & Share) */}
      <div className="absolute top-4 right-4 z-30 flex gap-2">
         <button 
          onClick={handleShare}
          className="p-2.5 rounded-full bg-white/90 backdrop-blur-sm shadow-sm hover:scale-110 transition-all group/share text-slate-500 hover:text-[#00C1D4]"
          title="Delen"
        >
          {isCopied ? <Check className="w-5 h-5 text-green-500" /> : <Share2 className="w-5 h-5" />}
        </button>

        <button 
          onClick={(e) => {
            e.stopPropagation(); // Prevent opening modal
            e.preventDefault();
            onToggleFavorite(course.id);
          }}
          className="p-2.5 rounded-full bg-white/90 backdrop-blur-sm shadow-sm hover:scale-110 transition-all group/heart"
          title={isFavorite ? "Verwijder uit favorieten" : "Opslaan als favoriet"}
        >
          <Heart 
            className={`w-5 h-5 transition-colors ${
              isFavorite 
                ? 'fill-red-500 text-red-500' 
                : 'text-slate-400 group-hover/heart:text-red-400'
            }`} 
          />
        </button>
      </div>

      <div className="relative h-52 overflow-hidden bg-slate-200">
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent z-10 opacity-60"></div>
        <img 
          src={displayImage} 
          alt={course.title} 
          onError={() => setHasError(true)}
          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
        />

        {/* Badges Area */}
        <div className="absolute top-4 left-4 z-20 flex flex-col gap-2 items-start">
            <span className={`px-3 py-1 rounded-lg text-xs font-black uppercase tracking-wider border backdrop-blur-sm bg-white/95 ${badgeColor}`}>
                {course.organizer}
            </span>
            {course.isNew && (
                <span className="px-3 py-1 rounded-lg text-xs font-black uppercase tracking-wider bg-red-500 text-white shadow-lg shadow-red-500/30 animate-pulse">
                    Nieuw
                </span>
            )}
        </div>

        <div className="absolute bottom-4 left-4 z-20 flex flex-col text-white shadow-sm">
             <div className="flex items-center gap-1.5 text-xs font-bold mb-1 opacity-90">
                 <Calendar className="w-3.5 h-3.5" />
                 {new Date(course.date).toLocaleDateString('nl-NL', { day: 'numeric', month: 'long', year: 'numeric' })}
             </div>
        </div>

        {/* Overlay Hover Effect */}
        <div className="absolute inset-0 bg-[#00C1D4]/80 z-20 opacity-0 group-hover:opacity-10 transition-opacity duration-300"></div>
      </div>

      <div className="p-6 flex-1 flex flex-col">
        <div className="flex items-start justify-between mb-3">
             <div className="flex items-center gap-1.5 text-xs font-bold text-slate-400 uppercase tracking-wide">
                <MapPin className="w-3.5 h-3.5" />
                {course.location}
            </div>
        </div>

        <h3 className="text-xl font-extrabold text-slate-800 mb-3 leading-tight group-hover:text-[#00C1D4] transition-colors">
          {course.title}
        </h3>

        <p className="text-slate-600 text-sm mb-5 line-clamp-3 flex-1 leading-relaxed">
          {course.description}
        </p>

        <div className="flex flex-wrap gap-2 mb-6">
            {course.tags.slice(0, 3).map(tag => (
                <span key={tag} className="flex items-center gap-1 text-[11px] font-bold bg-slate-50 text-slate-500 px-2.5 py-1 rounded-md border border-slate-100 uppercase tracking-wide">
                    {tag}
                </span>
            ))}
        </div>

        <div className="mt-auto pt-5 border-t border-slate-50 flex items-center justify-between">
            <span className="font-black text-xl text-[#7AB800]">
                {course.price === 0 ? 'Gratis' : `€${course.price},-`}
            </span>
            <button 
                className="inline-flex items-center gap-1.5 text-sm font-bold text-[#00C1D4] hover:text-[#0096a6] transition-colors group/link"
            >
                Bekijk details <ArrowRight className="w-4 h-4 transition-transform group-hover/link:translate-x-1" />
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { CourseCard } from './components/CourseCard';
import { AddCourseModal } from './components/AddCourseModal';
import { CourseDetailModal } from './components/CourseDetailModal';
import { AIAssistant } from './components/AIAssistant';
import { Course, SearchFilters, SortOption } from './types';
import { INITIAL_COURSES, REGIONS } from './constants';
import { Search, Filter, ChevronDown, Check, X, Lock, ArrowUpDown, Heart, SlidersHorizontal, Mail } from 'lucide-react';

const App: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>(INITIAL_COURSES);

  // Favorites State with LocalStorage
  const [favorites, setFavorites] = useState<string[]>(() => {
    const saved = localStorage.getItem('alo_kvlo_favorites');
    return saved ? JSON.parse(saved) : [];
  });

  const [filters, setFilters] = useState<SearchFilters>({
    query: '',
    region: 'Alle',
    dateStart: '',
    dateEnd: '',
    organizer: 'Alle',
    selectedTags: []
  });

  const [sortOption, setSortOption] = useState<SortOption>('date-asc');
  const [showOnlyFavorites, setShowOnlyFavorites] = useState(false);
  const [showMobileFilters, setShowMobileFilters] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);

  // State for Course Detail Modal
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  const [isTagDropdownOpen, setIsTagDropdownOpen] = useState(false);
  const tagDropdownRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  // Persist Favorites
  useEffect(() => {
    localStorage.setItem('alo_kvlo_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const toggleFavorite = (id: string) => {
    setFavorites(prev => 
      prev.includes(id) ? prev.filter(fav => fav !== id) : [...prev, id]
    );
  };

  // Close tag dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (tagDropdownRef.current && !tagDropdownRef.current.contains(event.target as Node)) {
        setIsTagDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const uniqueTags = useMemo(() => {
    const tags = new Set<string>();
    courses.forEach(course => course.tags.forEach(tag => tags.add(tag)));
    return Array.from(tags).sort();
  }, [courses]);

  // Filter & Sort Logic
  const filteredAndSortedCourses = useMemo(() => {
    let result = courses.filter(course => {
      const matchesQuery = 
        course.title.toLowerCase().includes(filters.query.toLowerCase()) || 
        course.description.toLowerCase().includes(filters.query.toLowerCase()) ||
        course.tags.some(tag => tag.toLowerCase().includes(filters.query.toLowerCase()));

      const matchesRegion = filters.region === 'Alle' || course.region === filters.region;

      const courseDate = new Date(course.date);
      const matchesDateStart = !filters.dateStart || courseDate >= new Date(filters.dateStart);
      const matchesDateEnd = !filters.dateEnd || courseDate <= new Date(filters.dateEnd);

      const matchesOrganizer = filters.organizer === 'Alle' || course.organizer === filters.organizer;

      const matchesTags = filters.selectedTags.length === 0 || 
        filters.selectedTags.some(tag => course.tags.includes(tag));

      const matchesFavorite = !showOnlyFavorites || favorites.includes(course.id);

      return matchesQuery && matchesRegion && matchesDateStart && matchesDateEnd && matchesOrganizer && matchesTags && matchesFavorite;
    });

    // Apply Sorting
    result.sort((a, b) => {
      if (sortOption === 'date-asc') return new Date(a.date).getTime() - new Date(b.date).getTime();
      if (sortOption === 'date-desc') return new Date(b.date).getTime() - new Date(a.date).getTime();
      if (sortOption === 'price-asc') return a.price - b.price;
      if (sortOption === 'price-desc') return b.price - a.price;
      return 0;
    });

    return result;
  }, [courses, filters, favorites, showOnlyFavorites, sortOption]);

  const handleAddCourse = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
  };

  const handleAdminCheck = (e: React.MouseEvent) => {
    e.preventDefault();
    setIsModalOpen(true);
  };

  const toggleTag = (tag: string) => {
    setFilters(prev => {
      const newTags = prev.selectedTags.includes(tag)
        ? prev.selectedTags.filter(t => t !== tag)
        : [...prev.selectedTags, tag];
      return { ...prev, selectedTags: newTags };
    });
  };

  const clearTags = () => {
    setFilters(prev => ({ ...prev, selectedTags: [] }));
  };

  const scrollToContent = () => {
    contentRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F9FAFB]">
      <Header />

      <Hero courseCount={courses.length} onScrollToContent={scrollToContent} />

      <main ref={contentRef} className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-16">

        {/* Mobile Filter Toggle */}
        <div className="md:hidden mb-4">
            <button 
                onClick={() => setShowMobileFilters(!showMobileFilters)}
                className="w-full bg-white border border-slate-200 p-3 rounded-xl flex items-center justify-center gap-2 font-bold text-slate-700 shadow-sm"
            >
                <SlidersHorizontal className="w-5 h-5 text-[#00C1D4]" />
