import React, { useState } from 'react';
import { Course, Organizer } from '../types';
import { REGIONS, DEFAULT_IMAGES } from '../constants';
import { X, Link as LinkIcon } from 'lucide-react';

interface AddCourseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (course: Course) => void;
}

export const AddCourseModal: React.FC<AddCourseModalProps> = ({ isOpen, onClose, onAdd }) => {
  const [formData, setFormData] = useState<Partial<Course>>({
    organizer: Organizer.KVLO,
    region: 'Landelijk',
    price: 0,
    tags: [],
    url: ''
  });
  const [tagInput, setTagInput] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.date || !formData.description) return;

    // Pick a random sporty image from our default set
    const randomImage = DEFAULT_IMAGES[Math.floor(Math.random() * DEFAULT_IMAGES.length)];

    const newCourse: Course = {
      id: Date.now().toString(),
      title: formData.title,
      organizer: formData.organizer as Organizer,
      date: formData.date,
      location: formData.location || 'Onbekend',
      region: formData.region || 'Landelijk',
      price: Number(formData.price) || 0,
      description: formData.description,
      tags: formData.tags || [],
      url: formData.url && formData.url.length > 0 ? formData.url : '#',
      imageUrl: randomImage,
      isNew: true
    };

    onAdd(newCourse);
    // Reset form slightly but keep some defaults for ease of use
    setFormData({
        organizer: Organizer.KVLO,
        region: 'Landelijk',
        price: 0,
        tags: [],
        url: ''
    });
    onClose();
  };

  const handleAddTag = () => {
    if (tagInput.trim()) {
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), tagInput.trim()]
      }));
      setTagInput('');
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-[#1e293b]/80 backdrop-blur-sm transition-opacity">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto transform transition-all">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center sticky top-0 bg-white z-10">
          <div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tight">Nieuwe Scholing</h2>
              <p className="text-sm text-slate-500 font-medium">Voeg een cursus toe aan de kalender</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-50 rounded-full transition-colors">
            <X className="w-6 h-6 text-slate-400 hover:text-red-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2 col-span-1 md:col-span-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Titel</label>
              <input 
                required
                type="text" 
                className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] focus:border-transparent outline-none transition-shadow"
                value={formData.title || ''}
                onChange={e => setFormData({...formData, title: e.target.value})}
                placeholder="Bijv: Workshop Freerunning Basis"
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Organisator</label>
              <select 
                className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow bg-white"
                value={formData.organizer}
                onChange={e => setFormData({...formData, organizer: e.target.value as Organizer})}
              >
                {Object.values(Organizer).map(org => (
                  <option key={org} value={org}>{org}</option>
                ))}
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Datum</label>
              <input 
                required
                type="date" 
                className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                value={formData.date || ''}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Locatie</label>
               <input 
                 type="text"
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 value={formData.location || ''}
                 onChange={e => setFormData({...formData, location: e.target.value})}
                 placeholder="Bijv: Sporthal De Pijp"
               />
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Regio</label>
               <select 
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow bg-white"
                 value={formData.region}
                 onChange={e => setFormData({...formData, region: e.target.value})}
               >
                 {REGIONS.map(r => <option key={r} value={r}>{r}</option>)}
               </select>
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Prijs (€)</label>
               <input 
                 type="number"
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 value={formData.price}
                 onChange={e => setFormData({...formData, price: Number(e.target.value)})}
               />
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                  Link naar info/aanmelden <LinkIcon className="w-3 h-3" />
               </label>
               <input 
                 type="url"
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 value={formData.url || ''}
                 onChange={e => setFormData({...formData, url: e.target.value})}
                 placeholder="https://www.aanbieder.nl/cursus"
               />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Omschrijving</label>
            <textarea 
              required
              rows={4}
              className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none resize-none transition-shadow"
              value={formData.description || ''}
              onChange={e => setFormData({...formData, description: e.target.value})}
              placeholder="Wat gaan de deelnemers leren?"
            />
          </div>

          <div className="space-y-2">
             <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Tags</label>
             <div className="flex gap-2">
               <input 
                 type="text" 
                 className="flex-1 px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 placeholder="Bijv: PO, Motorisch Leren..."
                 value={tagInput}
                 onChange={e => setTagInput(e.target.value)}
                 onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), handleAddTag())}
               />
               <button 
                 type="button" 
                 onClick={handleAddTag}
                 className="px-4 py-2.5 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors font-bold"
               >
                 +
               </button>
             </div>
             <div className="flex flex-wrap gap-2 mt-2">
               {formData.tags?.map(tag => (
                 <span key={tag} className="bg-[#E0F7FA] text-[#006064] px-2.5 py-1 rounded-md text-xs font-bold flex items-center gap-1 border border-[#B2EBF2]">
                   {tag}
                   <button 
                     type="button"
                     onClick={() => setFormData({...formData, tags: formData.tags?.filter(t => t !== tag)})}
                     className="hover:text-red-500"
                   >
                     ×
                   </button>
                 </span>
               ))}
             </div>
          </div>

          <div className="pt-6 flex justify-end gap-3 border-t border-slate-50">
            <button 
              type="button" 
              onClick={onClose}
              className="px-6 py-2.5 text-slate-500 font-bold hover:bg-slate-50 rounded-lg transition-colors"
            >
              Annuleren
            </button>
            <button 
              type="submit"
              className="px-8 py-2.5 bg-gradient-to-r from-[#7AB800] to-[#6da500] text-white font-bold rounded-lg hover:shadow-lg hover:shadow-green-500/30 transition-all transform hover:-translate-y-0.5"
            >
              Toevoegen
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useEffect } from 'react';
import { CheckCircle2, X } from 'lucide-react';

interface ToastProps {
  message: string;
  isVisible: boolean;
  onClose: () => void;
}

export const Toast: React.FC<ToastProps> = ({ message, isVisible, onClose }) => {
  useEffect(() => {
    if (isVisible) {
      const timer = setTimeout(() => {
        onClose();
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [isVisible, onClose]);

  return (
    <div 
      className={`fixed top-4 left-1/2 -translate-x-1/2 z-[110] flex items-center gap-3 bg-[#1e293b] text-white px-6 py-4 rounded-xl shadow-2xl transition-all duration-500 ease-in-out border-l-4 border-[#7AB800]
      ${isVisible ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}
    >
      <CheckCircle2 className="w-6 h-6 text-[#7AB800]" />
      <div className="flex flex-col">
          <span className="font-bold text-sm">Succes!</span>
          <span className="text-xs text-slate-300">{message}</span>
      </div>
      <button onClick={onClose} className="ml-4 hover:bg-white/10 p-1 rounded-full transition-colors">
        <X className="w-4 h-4 text-slate-400" />
      </button>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { CourseCard } from './components/CourseCard';
import { AddCourseModal } from './components/AddCourseModal';
import { CourseDetailModal } from './components/CourseDetailModal';
import { AIAssistant } from './components/AIAssistant';
import { Toast } from './components/Toast';
import { Course, SearchFilters, SortOption } from './types';
import { INITIAL_COURSES, REGIONS } from './constants';
import { Search, Filter, ChevronDown, Check, X, Lock, ArrowUpDown, Heart, SlidersHorizontal, Mail } from 'lucide-react';

const App: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>(INITIAL_COURSES);

  // Favorites State with LocalStorage
  const [favorites, setFavorites] = useState<string[]>(() => {
    const saved = localStorage.getItem('alo_kvlo_favorites');
    return saved ? JSON.parse(saved) : [];
  });

  const [filters, setFilters] = useState<SearchFilters>({
    query: '',
    region: 'Alle',
    dateStart: '',
    dateEnd: '',
    organizer: 'Alle',
    selectedTags: []
  });

  const [sortOption, setSortOption] = useState<SortOption>('date-asc');
  const [showOnlyFavorites, setShowOnlyFavorites] = useState(false);
  const [showMobileFilters, setShowMobileFilters] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [toast, setToast] = useState<{message: string, isVisible: boolean}>({ message: '', isVisible: false });

  // State for Course Detail Modal
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  const [isTagDropdownOpen, setIsTagDropdownOpen] = useState(false);
  const tagDropdownRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  // Persist Favorites
  useEffect(() => {
    localStorage.setItem('alo_kvlo_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const toggleFavorite = (id: string) => {
    setFavorites(prev => 
      prev.includes(id) ? prev.filter(fav => fav !== id) : [...prev, id]
    );
  };

  const showToast = (message: string) => {
    setToast({ message, isVisible: true });
  };

  // Close tag dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (tagDropdownRef.current && !tagDropdownRef.current.contains(event.target as Node)) {
        setIsTagDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const uniqueTags = useMemo(() => {
    const tags = new Set<string>();
    courses.forEach(course => course.tags.forEach(tag => tags.add(tag)));
    return Array.from(tags).sort();
  }, [courses]);

  // Filter & Sort Logic
  const filteredAndSortedCourses = useMemo(() => {
    let result = courses.filter(course => {
      const matchesQuery = 
        course.title.toLowerCase().includes(filters.query.toLowerCase()) || 
        course.description.toLowerCase().includes(filters.query.toLowerCase()) ||
        course.tags.some(tag => tag.toLowerCase().includes(filters.query.toLowerCase()));

      const matchesRegion = filters.region === 'Alle' || course.region === filters.region;

      const courseDate = new Date(course.date);
      const matchesDateStart = !filters.dateStart || courseDate >= new Date(filters.dateStart);
      const matchesDateEnd = !filters.dateEnd || courseDate <= new Date(filters.dateEnd);

      const matchesOrganizer = filters.organizer === 'Alle' || course.organizer === filters.organizer;

      const matchesTags = filters.selectedTags.length === 0 || 
        filters.selectedTags.some(tag => course.tags.includes(tag));

      const matchesFavorite = !showOnlyFavorites || favorites.includes(course.id);

      return matchesQuery && matchesRegion && matchesDateStart && matchesDateEnd && matchesOrganizer && matchesTags && matchesFavorite;
    });

    // Apply Sorting
    result.sort((a, b) => {
      if (sortOption === 'date-asc') return new Date(a.date).getTime() - new Date(b.date).getTime();
      if (sortOption === 'date-desc') return new Date(b.date).getTime() - new Date(a.date).getTime();
      if (sortOption === 'price-asc') return a.price - b.price;
      if (sortOption === 'price-desc') return b.price - a.price;
      return 0;
    });

    return result;
  }, [courses, filters, favorites, showOnlyFavorites, sortOption]);

  const handleAddCourse = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
    showToast(`"${newCourse.title}" is succesvol toegevoegd!`);
  };

  const handleAdminCheck = (e: React.MouseEvent) => {
    e.preventDefault();
    setIsModalOpen(true);
  };

  const toggleTag = (tag: string) => {
    setFilters(prev => {
      const newTags = prev.selectedTags.includes(tag)
        ? prev.selectedTags.filter(t => t !== tag)
        : [...prev.selectedTags, tag];
      return { ...prev, selectedTags: newTags };
    });
  };

  const clearTags = () => {
    setFilters(prev => ({ ...prev, selectedTags: [] }));
  };

  const scrollToContent = () => {
    contentRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F9FAFB]">
      {/* Toast Notification */}
      <Toast 
        message={toast.message} 
        isVisible={toast.isVisible} 
        onClose={() => setToast(prev => ({ ...prev, isVisible: false }))} 
      />

      <Header />

      <Hero courseCount={courses.length} onScrollToContent={scrollToContent} />

      <main ref={contentRef} className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-16">

        {/* Mobile Filter Toggle */}
        <div className="md:hidden mb-4">
            <button 
                onClick={() => setShowMobileFilters(!showMobileFilters)}
                className="w-full bg-white border border-slate-200 p-3 rounded-xl flex items-center justify-center gap-2 font-bold text-slate-700 shadow-sm"
            >
                <SlidersHorizontal className="w-5 h-5 text-[#00C1D4]" />
                {showMobileFilters ? 'Verberg Filters' : 'Toon Zoekfilters'}
            </button>
        </div>

        {/* Search & Filter Bar */}
        <div className={`bg-white p-6 rounded-2xl shadow-sm border border-slate-100 mb-10 max-w-6xl mx-auto ring-1 ring-slate-900/5 md:-mt-12 relative z-20 transition-all duration-300 ${showMobileFilters ? 'block' : 'hidden md:block'}`}>
          <div className="space-y-5">

            {/* Top Row: Text Search & Sort */}
            <div className="flex flex-col md:flex-row gap-4">
              <div className="relative flex-1 group">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5 group-focus-within:text-[#7AB800] transition-colors" />
                  <input 
                    type="text" 
                    placeholder="Zoek op titel, onderwerp of trefwoord..." 
                    className="w-full pl-12 pr-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-[#00C1D4] focus:border-[#00C1D4] outline-none transition-all text-slate-700 bg-slate-50 focus:bg-white"
                    value={filters.query}
                    onChange={e => setFilters({...filters, query: e.target.value})}
                  />
              </div>

              {/* Sort Dropdown */}
              <div className="relative md:w-56 group">
                 <ArrowUpDown className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 group-focus-within:text-[#7AB800]" />
                 <select 
                   className="w-full h-full pl-10 pr-8 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-[#00C1D4] focus:border-[#00C1D4] outline-none appearance-none bg-white text-sm cursor-pointer font-medium text-slate-700"
                   value={sortOption}
                   onChange={e => setSortOption(e.target.value as SortOption)}
                 >
                   <option value="date-asc">Datum (Eerstvolgende)</option>
                   <option value="date-desc">Datum (Nieuwste)</option>
                   <option value="price-asc">Prijs (Laag - Hoog)</option>
                   <option value="price-desc">Prijs (Hoog - Laag)</option>
                 </select>
                 <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
              </div>
            </div>

            {/* Middle Row: Filters Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">

              <div className="sm:col-span-2 flex gap-2 items-center bg-slate-50 p-1.5 rounded-xl border border-slate-200 h-12 focus-within:ring-2 focus-within:ring-[#00C1D4] focus-within:border-transparent transition-all">
                <div className="relative flex-1 h-full">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <span className="text-xs font-bold text-slate-400 uppercase">Van</span>
                    </div>
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-2 h-full bg-transparent text-sm focus:outline-none text-slate-700 cursor-pointer font-medium"
                      value={filters.dateStart}
                      onChange={e => setFilters({...filters, dateStart: e.target.value})}
                    />
                </div>
                <div className="w-px h-6 bg-slate-300"></div>
                <div className="relative flex-1 h-full">
                     <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <span className="text-xs font-bold text-slate-400 uppercase">Tot</span>
                    </div>
                    <input 
                      type="date" 
                      className="w-full pl-10 pr-2 h-full bg-transparent text-sm focus:outline-none text-slate-700 cursor-pointer font-medium"
                      value={filters.dateEnd}
                      onChange={e => setFilters({...filters, dateEnd: e.target.value})}
                    />
                </div>
              </div>

              <div className="relative h-12 group">
                <Filter className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 group-focus-within:text-[#7AB800]" />
                <select 
                  className="w-full h-full pl-10 pr-8 border border-slate-200 rounded-xl focus:ring-2 focus:ring-[#00C1D4] focus:border-[#00C1D4] outline-none appearance-none bg-white text-sm cursor-pointer font-medium text-slate-700 shadow-sm"
                  value={filters.region}
                  onChange={e => setFilters({...filters, region: e.target.value})}
                >
                  <option value="Alle">Alle Regio's</option>
                  {REGIONS.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
              </div>

              <div className="relative h-12">
                <select 
                  className="w-full h-full px-4 pr-8 border border-slate-200 rounded-xl focus:ring-2 focus:ring-[#00C1D4] focus:border-[#00C1D4] outline-none appearance-none bg-white text-sm cursor-pointer font-medium text-slate-700 shadow-sm"
                  value={filters.organizer}
                  onChange={e => setFilters({...filters, organizer: e.target.value})}
                >
                  <option value="Alle">Alle Organisatoren</option>
                  <option value="KVLO">KVLO</option>
                  <option value="ALO Nederland">ALO Nederland</option>
                  <option value="Gezamenlijk">Gezamenlijk</option>
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
              </div>
            </div>

            {/* Bottom Row: Tags & Favorites Toggle */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">

              <div className="relative" ref={tagDropdownRef}>
                <button 
                  onClick={() => setIsTagDropdownOpen(!isTagDropdownOpen)}
                  className={`w-full md:w-auto min-w-[200px] flex items-center justify-between gap-3 px-4 py-2.5 border rounded-xl text-sm font-bold transition-all cursor-pointer ${
                    isTagDropdownOpen || filters.selectedTags.length > 0
                      ? 'border-[#00C1D4] text-[#008d9b] bg-[#e0faff]' 
                      : 'border-slate-200 text-slate-600 hover:border-[#7AB800] hover:text-[#7AB800]'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    <Filter className="w-4 h-4" />
                    <span>
                      {filters.selectedTags.length === 0 
                        ? 'Filter op Tags' 
                        : `${filters.selectedTags.length} tag${filters.selectedTags.length > 1 ? 's' : ''} geselecteerd`}
                    </span>
                  </div>
                  <ChevronDown className={`w-4 h-4 transition-transform ${isTagDropdownOpen ? 'rotate-180' : ''}`} />
                </button>

                {isTagDropdownOpen && (
                  <div className="absolute top-full left-0 mt-2 w-full md:w-[450px] bg-white rounded-xl shadow-xl border border-slate-100 p-5 z-50 animate-in fade-in slide-in-from-top-2 ring-1 ring-slate-900/5">
                    <div className="flex justify-between items-center mb-4 pb-2 border-b border-slate-100">
                      <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Kies onderwerpen</span>
                      {filters.selectedTags.length > 0 && (
                        <button onClick={clearTags} className="text-xs text-red-500 hover:text-red-600 font-bold">
                          WIS ALLES
                        </button>
                      )}
                    </div>
                    <div className="flex flex-wrap gap-2 max-h-[250px] overflow-y-auto custom-scrollbar">
                      {uniqueTags.map(tag => {
                        const isSelected = filters.selectedTags.includes(tag);
                        return (
                          <button
                            key={tag}
                            onClick={() => toggleTag(tag)}
                            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-all cursor-pointer border ${
                              isSelected 
                                ? 'bg-gradient-to-r from-[#7AB800] to-[#6da500] text-white border-transparent shadow-sm' 
                                : 'bg-white text-slate-600 border-slate-200 hover:border-[#00C1D4] hover:text-[#00C1D4]'
                            }`}
                          >
                            {tag}
                            {isSelected && <Check className="w-3 h-3" />}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>

              {/* Favorites Toggle */}
              <button
                onClick={() => setShowOnlyFavorites(!showOnlyFavorites)}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold transition-all border ${
                  showOnlyFavorites
                    ? 'bg-red-50 text-red-500 border-red-200'
                    : 'bg-white text-slate-500 border-slate-200 hover:text-red-500 hover:border-red-200'
                }`}
              >
                <Heart className={`w-4 h-4 ${showOnlyFavorites ? 'fill-red-500' : ''}`} />
                <span>Mijn Favorieten ({favorites.length})</span>
              </button>

            </div>

            {/* Active Filters Display */}
            {filters.selectedTags.length > 0 && (
                <div className="flex flex-wrap gap-2 pt-2">
                    {filters.selectedTags.map(tag => (
                        <span key={tag} className="flex items-center gap-1 bg-[#F0FDF4] text-[#7AB800] border border-[#DCFCE7] text-xs font-bold px-3 py-1 rounded-full animate-in zoom-in-95">
                            {tag}
                            <button onClick={() => toggleTag(tag)} className="hover:text-red-500 transition-colors">
                                <X className="w-3 h-3" />
                            </button>
                        </span>
                    ))}
                </div>
            )}

          </div>

          <div className="mt-6 pt-4 border-t border-slate-100 flex justify-between items-center text-sm text-slate-500">
             <div className="flex items-center gap-6">
               <span className="font-medium">{filteredAndSortedCourses.length} scholingen gevonden</span>
               <button 
                type="button"
                onClick={handleAdminCheck}
                className="flex items-center gap-1 text-slate-400 hover:text-[#00C1D4] transition-colors text-xs hover:bg-[#F0FDFA] px-2 py-1 rounded cursor-pointer font-medium"
               >
                 <Lock className="w-3 h-3" />
                 <span>Toevoegen</span>
               </button>
             </div>

             {(filters.query || filters.region !== 'Alle' || filters.organizer !== 'Alle' || filters.dateStart || filters.dateEnd || filters.selectedTags.length > 0 || showOnlyFavorites) && (
                <button 
                    onClick={() => {
                      setFilters({
                          query: '', 
                          region: 'Alle', 
                          dateStart: '', 
                          dateEnd: '', 
                          organizer: 'Alle', 
                          selectedTags: []
                      });
                      setShowOnlyFavorites(false);
                    }}
                    className="text-[#00C1D4] font-bold hover:underline cursor-pointer"
                >
                    Filters wissen
                </button>
             )}
          </div>
        </div>

        {/* Results Grid */}
        {filteredAndSortedCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredAndSortedCourses.map((course, index) => (
               <div 
                key={course.id} 
                className="animate-in fade-in slide-in-from-bottom-4 duration-500 fill-mode-backwards"
                style={{ animationDelay: `${index * 50}ms` }}
               >
                  <CourseCard 
                    course={course} 
                    isFavorite={favorites.includes(course.id)}
                    onToggleFavorite={toggleFavorite}
                    onClick={(c) => setSelectedCourse(c)}
                  />
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
            <h3 className="text-xl font-bold text-slate-800">Geen scholingen gevonden</h3>
            <p className="text-slate-500 mt-2">
              {showOnlyFavorites 
                ? "Je hebt nog geen favorieten gemarkeerd." 
                : "Pas je filters aan of gebruik de slimme zoekhulp rechtsonder."}
            </p>
          </div>
        )}

      </main>

      <footer className="bg-[#1e293b] text-slate-300 py-16 border-t-8 border-[#7AB800]">
          <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 md:grid-cols-3 gap-12">
              <div className="space-y-6">
                  <div>
                    <h4 className="text-white font-bold text-xl mb-4">Over LO Academie</h4>
                    <p className="text-sm leading-relaxed text-slate-400">
                        LO Academie is hét platform waar <strong>KVLO</strong> en <strong>ALO Nederland</strong> hun krachten bundelen. Eén centrale plek voor alle bijscholingen, cursussen en congressen voor de professional in bewegingsonderwijs.
                    </p>
                  </div>
                  <div className="pt-4 border-t border-slate-800">
                     <h4 className="text-white font-bold text-sm uppercase tracking-wider mb-3">Nieuwsbrief</h4>
                     <p className="text-xs text-slate-400 mb-3">Blijf op de hoogte van het laatste scholingsaanbod.</p>
                     <div className="flex gap-2">
                        <input type="email" placeholder="Je e-mailadres" className="bg-slate-800 border-slate-700 text-sm px-3 py-2 rounded text-slate-200 outline-none focus:ring-1 focus:ring-[#7AB800] w-full" />
                        <button className="bg-[#7AB800] text-white p-2 rounded hover:bg-[#6da500] transition-colors"><Mail className="w-4 h-4" /></button>
                     </div>
                  </div>
              </div>
              <div>
                   <h4 className="text-white font-bold text-xl mb-6">Partners</h4>
                   <ul className="space-y-3 text-sm font-medium">
                       <li><a href="https://www.kvlo.nl" target="_blank" className="hover:text-[#7AB800] transition-colors flex items-center gap-2">Koninklijke Vakvereniging Lichamelijke Opvoeding</a></li>
                       <li><a href="https://www.alo.nl" target="_blank" className="hover:text-[#00C1D4] transition-colors flex items-center gap-2">ALO Nederland</a></li>
                   </ul>
              </div>
              <div>
                  <h4 className="text-white font-bold text-xl mb-6">Contact</h4>
                  <p className="text-sm text-slate-400">Heb je vragen over een specifieke cursus? Neem dan direct contact op met de aanbieder via de 'Info & Aanmelden' knop bij de betreffende scholing.</p>
              </div>
          </div>
          <div className="max-w-7xl mx-auto px-4 mt-16 pt-8 border-t border-slate-800 text-center text-sm font-medium text-slate-500">
              &copy; {new Date().getFullYear()} LO Academie. Een initiatief voor en door bewegingsonderwijs.
          </div>
      </footer>

      {/* Admin Modal */}
      <AddCourseModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onAdd={handleAddCourse}
      />

      {/* Course Detail Modal */}
      <CourseDetailModal 
        isOpen={!!selectedCourse} 
        course={selectedCourse} 
        onClose={() => setSelectedCourse(null)} 
      />

      {/* AI Assistant */}
      <AIAssistant courses={courses} />

    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Course, Organizer } from '../types';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon } from 'lucide-react';

interface CalendarViewProps {
  courses: Course[];
  onSelectCourse: (course: Course) => void;
}

export const CalendarView: React.FC<CalendarViewProps> = ({ courses, onSelectCourse }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  // Helper to get days in month
  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const days = new Date(year, month + 1, 0).getDate();
    return Array.from({ length: days }, (_, i) => new Date(year, month, i + 1));
  };

  const days = getDaysInMonth(currentDate);
  const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay(); // 0 = Sun

  // Adjust so Monday is first day (0 = Mon, 6 = Sun)
  const startOffset = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const monthName = currentDate.toLocaleDateString('nl-NL', { month: 'long', year: 'numeric' });

  const getCoursesForDate = (date: Date) => {
    return courses.filter(c => {
      const cDate = new Date(c.date);
      return cDate.getDate() === date.getDate() && 
             cDate.getMonth() === date.getMonth() && 
             cDate.getFullYear() === date.getFullYear();
    });
  };

  const weekDays = ['Ma', 'Di', 'Wo', 'Do', 'Vr', 'Za', 'Zo'];

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden animate-in fade-in duration-300">

      {/* Header */}
      <div className="p-6 flex items-center justify-between border-b border-slate-100">
        <h2 className="text-xl font-bold text-slate-800 capitalize flex items-center gap-2">
            <CalendarIcon className="w-5 h-5 text-[#00C1D4]" />
            {monthName}
        </h2>
        <div className="flex gap-2">
          <button onClick={prevMonth} className="p-2 hover:bg-slate-50 rounded-lg border border-slate-200 transition-colors">
            <ChevronLeft className="w-5 h-5 text-slate-600" />
          </button>
          <button onClick={nextMonth} className="p-2 hover:bg-slate-50 rounded-lg border border-slate-200 transition-colors">
            <ChevronRight className="w-5 h-5 text-slate-600" />
          </button>
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-7 border-b border-slate-100">
        {weekDays.map(day => (
          <div key={day} className="py-3 text-center text-xs font-bold text-slate-400 uppercase tracking-wider border-r border-slate-50 last:border-none">
