          <div key={`empty-${i}`} className="bg-slate-50 border-r border-b border-slate-100/50" />
        ))}

        {days.map(date => {
            const daysCourses = getCoursesForDate(date);
            const isToday = new Date().toDateString() === date.toDateString();

            return (
                <div key={date.toISOString()} className="bg-white border-r border-b border-slate-100 relative group transition-colors hover:bg-slate-50/50 overflow-hidden p-1">
                    <span className={`absolute top-2 right-2 w-7 h-7 flex items-center justify-center text-xs font-bold rounded-full
