                        {date.getDate()}
                    </span>

                    <div className="mt-7 flex flex-col gap-1 overflow-y-auto max-h-[85px] custom-scrollbar">
                        {daysCourses.map(course => (
                            <button 
                                key={course.id}
                                onClick={() => onSelectCourse(course)}
                                className={`text-[10px] text-left px-2 py-1 rounded border truncate font-medium transition-all hover:scale-[1.02]
