import React, { useEffect, useRef } from 'react';
import { Course, Organizer } from '../types';
import * as L from 'leaflet';
import { MapPin, ExternalLink } from 'lucide-react';

interface MapViewProps {
  courses: Course[];
  onSelectCourse: (course: Course) => void;
}

// Helper to estimate coordinates based on Dutch city names (Demo purpose)
const getCoordinates = (location: string, region: string): [number, number] => {
  const loc = location.toLowerCase();

  // Specific Cities
  if (loc.includes('nijmegen')) return [51.8449, 5.8676];
  if (loc.includes('amsterdam')) return [52.3676, 4.9041];
  if (loc.includes('meppel') || loc.includes('wanneperveen')) return [52.6936, 6.1945];
  if (loc.includes('alkmaar')) return [52.6296, 4.7571];
  if (loc.includes('zeist')) return [52.0907, 5.2328];
  if (loc.includes('ede')) return [52.0305, 5.6664];
  if (loc.includes('rotterdam')) return [51.9244, 4.4777];
  if (loc.includes('leiden')) return [52.1601, 4.4970];
  if (loc.includes('zwolle')) return [52.5168, 6.0830];
  if (loc.includes('groningen')) return [53.2194, 6.5665];
  if (loc.includes('eindhoven')) return [51.4416, 5.4697];
  if (loc.includes('tilburg')) return [51.5555, 5.0913];
  if (loc.includes('maastricht')) return [50.8514, 5.6910];
  if (loc.includes('utrecht')) return [52.0907, 5.1214];
  if (loc.includes('arnhem')) return [51.9851, 5.8987];
  if (loc.includes('den haag') || loc.includes('s-gravenhage')) return [52.0705, 4.3007];

  // Region Fallbacks (approximate centers)
  if (region === 'Noord') return [53.0, 6.5]; // Friesland/Groningen area
  if (region === 'Oost') return [52.2, 6.5]; // Gelderland/Overijssel
  if (region === 'Zuid') return [51.5, 5.0]; // Brabant/Limburg
  if (region === 'West') return [52.1, 4.5]; // Randstad

  // Default Center of NL
  return [52.1326, 5.2913]; 
};

export const MapView: React.FC<MapViewProps> = ({ courses, onSelectCourse }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<L.Map | null>(null);

  useEffect(() => {
    if (!mapRef.current || leafletMap.current) return;

    // Initialize Map
    leafletMap.current = L.map(mapRef.current).setView([52.1326, 5.2913], 7); // Center of NL

    // Add Tiles (OpenStreetMap)
    L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
      subdomains: 'abcd',
      maxZoom: 19
    }).addTo(leafletMap.current);

    // Clean up on unmount
    return () => {
      if (leafletMap.current) {
        leafletMap.current.remove();
        leafletMap.current = null;
      }
    };
  }, []);

  // Update Markers when courses change
  useEffect(() => {
    if (!leafletMap.current) return;

    // Clear existing markers
    leafletMap.current.eachLayer((layer) => {
        if (layer instanceof L.Marker) {
            leafletMap.current?.removeLayer(layer);
        }
    });

    courses.forEach(course => {
        if (course.location === 'Online') return; // Skip online courses

        const coords = getCoordinates(course.location, course.region);

        // Custom color based on organizer
        const color = course.organizer === Organizer.KVLO ? '#7AB800' : course.organizer === Organizer.ALO ? '#00C1D4' : '#7e22ce';

        const customIcon = L.divIcon({
            className: 'custom-div-icon',
            html: `<div style="background-color: ${color}; width: 12px; height: 12px; border-radius: 50%; border: 2px solid white; box-shadow: 0 0 4px rgba(0,0,0,0.3);"></div>`,
            iconSize: [12, 12],
            iconAnchor: [6, 6]
        });

        const marker = L.marker(coords, { icon: customIcon }).addTo(leafletMap.current!);

        // Create Popup Content properly using DOM element to attach event listener
        const popupContent = document.createElement('div');
        popupContent.innerHTML = `
            <div class="p-1">
                <span class="text-[10px] font-bold uppercase tracking-wider text-slate-500 mb-1 block">${course.organizer}</span>
                <h3 class="font-bold text-slate-800 text-sm mb-1 leading-tight">${course.title}</h3>
                <p class="text-xs text-slate-500 mb-2">${new Date(course.date).toLocaleDateString('nl-NL')}</p>
                <button id="btn-${course.id}" class="w-full bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold py-1.5 px-3 rounded flex items-center justify-center gap-1 transition-colors">
                    Details bekijken
                </button>
            </div>
        `;

        marker.bindPopup(popupContent);

        // Leaflet handles popup DOM insertion, we need to wait for it to open to attach listener?
        // Actually, easier way: bind 'popupopen' event to marker
        marker.on('popupopen', () => {
            const btn = document.getElementById(`btn-${course.id}`);
            if (btn) {
                btn.onclick = () => onSelectCourse(course);
            }
        });
    });

  }, [courses, onSelectCourse]);

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden h-[600px] relative animate-in fade-in duration-300">
        <div ref={mapRef} className="w-full h-full z-0" />
        <div className="absolute bottom-4 right-4 bg-white/90 backdrop-blur px-4 py-2 rounded-lg shadow-lg text-xs font-medium z-[400] border border-slate-200">
            <div className="flex items-center gap-3">
                <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-[#7AB800]"></div> KVLO</span>
                <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-[#00C1D4]"></div> ALO</span>
            </div>
        </div>
    </div>
  );
};

