import { DEFAULT_IMAGES } from '../constants';

interface CourseCardProps {
  course: Course;
  isFavorite: boolean;
  onToggleFavorite: (id: string) => void;
  onClick: (course: Course) => void;
  isAdmin?: boolean;
  onEdit?: () => void;
}

export const CourseCard: React.FC<CourseCardProps> = ({ course, isFavorite, onToggleFavorite, onClick, isAdmin, onEdit }) => {
  const [hasError, setHasError] = useState(false);
  const [isCopied, setIsCopied] = useState(false);

  const isKVLO = course.organizer === Organizer.KVLO;
  const isALO = course.organizer === Organizer.ALO;

  useEffect(() => {
    setHasError(false);
  }, [course.imageUrl]);

  const fallbackIndex = course.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0) % DEFAULT_IMAGES.length;
  const displayImage = !hasError && course.imageUrl ? course.imageUrl : DEFAULT_IMAGES[fallbackIndex];

  const badgeColor = isKVLO 
    ? 'bg-[#7AB800]/10 text-[#5a8700] border-[#7AB800]/20' 
    : isALO 
      ? 'bg-[#00C1D4]/10 text-[#008d9b] border-[#00C1D4]/20'
      : 'bg-purple-100 text-purple-700 border-purple-200';

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent opening modal
    e.preventDefault();
    const shareData = {
      title: course.title,
      text: `Bekijk deze scholing op LO Academie: ${course.title}`,
      url: window.location.href
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(`${course.title} - ${course.url}`);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  return (
    <div 
      onClick={() => onClick(course)}
      className="group bg-white rounded-2xl border border-slate-100 shadow-sm hover:shadow-xl hover:shadow-slate-200/50 transition-all duration-300 flex flex-col h-full overflow-hidden hover:-translate-y-1 relative cursor-pointer"
