import { AddCourseModal } from './components/AddCourseModal';
import { CourseDetailModal } from './components/CourseDetailModal';
import { AIAssistant } from './components/AIAssistant';
import { Toast } from './components/Toast';
import { CalendarView } from './components/CalendarView';
import { MapView } from './components/MapView';
import { Course, SearchFilters, SortOption } from './types';
import { INITIAL_COURSES, REGIONS } from './constants';
import { Search, Filter, ChevronDown, Check, X, Lock, Unlock, ArrowUpDown, Heart, SlidersHorizontal, Mail, LayoutGrid, Calendar as CalendarIcon, Map as MapIcon, GraduationCap } from 'lucide-react';

type ViewMode = 'list' | 'calendar' | 'map';

const App: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>(INITIAL_COURSES);

  // Favorites State with LocalStorage
  const [favorites, setFavorites] = useState<string[]>(() => {
    const saved = localStorage.getItem('alo_kvlo_favorites');
    return saved ? JSON.parse(saved) : [];
  });

  const [filters, setFilters] = useState<SearchFilters>({
    query: '',
    region: 'Alle',
    dateStart: '',
    dateEnd: '',
    organizer: 'Alle',
    selectedTags: []
  });

  const [sortOption, setSortOption] = useState<SortOption>('date-asc');
  const [showOnlyFavorites, setShowOnlyFavorites] = useState(false);
  const [showMobileFilters, setShowMobileFilters] = useState(false);

  // View Mode State
  const [viewMode, setViewMode] = useState<ViewMode>('list');

  // Admin & Modal State
  const [isAdmin, setIsAdmin] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [courseToEdit, setCourseToEdit] = useState<Course | undefined>(undefined);

  const [toast, setToast] = useState<{message: string, isVisible: boolean}>({ message: '', isVisible: false });

  // State for Course Detail Modal
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  const [isTagDropdownOpen, setIsTagDropdownOpen] = useState(false);
  const tagDropdownRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  // Persist Favorites
  useEffect(() => {
    localStorage.setItem('alo_kvlo_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const toggleFavorite = (id: string) => {
    setFavorites(prev => 
      prev.includes(id) ? prev.filter(fav => fav !== id) : [...prev, id]
    );
  };

  const showToast = (message: string) => {
    setToast({ message, isVisible: true });
  };

  // Close tag dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (tagDropdownRef.current && !tagDropdownRef.current.contains(event.target as Node)) {
        setIsTagDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const uniqueTags = useMemo(() => {
    const tags = new Set<string>();
    courses.forEach(course => course.tags.forEach(tag => tags.add(tag)));
    return Array.from(tags).sort();
  }, [courses]);

  // Filter & Sort Logic
  const filteredAndSortedCourses = useMemo(() => {
    // Robust date string comparison (YYYY-MM-DD)
    const todayStr = new Date().toISOString().split('T')[0];

    let result = courses.filter(course => {
      // 1. FILTER PAST COURSES (String comparison works perfectly for ISO dates)
      // If course date is strictly smaller than today, it's in the past.
      if (course.date < todayStr) return false;

      // 2. SEARCH & TEXT FILTER
      const matchesQuery = 
        course.title.toLowerCase().includes(filters.query.toLowerCase()) || 
        course.description.toLowerCase().includes(filters.query.toLowerCase()) ||
        course.tags.some(tag => tag.toLowerCase().includes(filters.query.toLowerCase()));

      const matchesRegion = filters.region === 'Alle' || course.region === filters.region;

      // Date Range Filters
      const matchesDateStart = !filters.dateStart || course.date >= filters.dateStart;
      const matchesDateEnd = !filters.dateEnd || course.date <= filters.dateEnd;

      const matchesOrganizer = filters.organizer === 'Alle' || course.organizer === filters.organizer;

      const matchesTags = filters.selectedTags.length === 0 || 
        filters.selectedTags.some(tag => course.tags.includes(tag));

      const matchesFavorite = !showOnlyFavorites || favorites.includes(course.id);

      return matchesQuery && matchesRegion && matchesDateStart && matchesDateEnd && matchesOrganizer && matchesTags && matchesFavorite;
    });

    // Apply Sorting
    result.sort((a, b) => {
      if (sortOption === 'date-asc') return a.date.localeCompare(b.date);
      if (sortOption === 'date-desc') return b.date.localeCompare(a.date);
      if (sortOption === 'price-asc') return a.price - b.price;
      if (sortOption === 'price-desc') return b.price - a.price;
      return 0;
    });

    return result;
  }, [courses, filters, favorites, showOnlyFavorites, sortOption]);

  const handleSaveCourse = (savedCourse: Course) => {
    setCourses(prevCourses => {
      const exists = prevCourses.some(c => c.id === savedCourse.id);

      if (exists) {
        showToast(`"${savedCourse.title}" is succesvol bijgewerkt!`);
        return prevCourses.map(c => c.id === savedCourse.id ? savedCourse : c);
      } else {
        showToast(`"${savedCourse.title}" is succesvol toegevoegd!`);
        return [savedCourse, ...prevCourses];
      }
    });
    setCourseToEdit(undefined);
  };

  const handleDeleteCourse = (id: string) => {
     if(window.confirm("Weet je zeker dat je deze scholing wilt verwijderen?")) {
        setCourses(prev => prev.filter(c => c.id !== id));
        showToast("Scholing verwijderd");
        setCourseToEdit(undefined);
        setIsModalOpen(false);
     }
