      const password = window.prompt("Voer wachtwoord in voor beheer (Demo: 'admin')");
      if (password === 'admin') {
        setIsAdmin(true);
        showToast("Beheerdersmodus actief");
      } else if (password) {
        alert("Onjuist wachtwoord");
      }
    }
  };

  const openAddModal = () => {
    setCourseToEdit(undefined);
    setIsModalOpen(true);
  };

  const toggleTag = (tag: string) => {
    setFilters(prev => {
      const newTags = prev.selectedTags.includes(tag)
        ? prev.selectedTags.filter(t => t !== tag)
        : [...prev.selectedTags, tag];
      return { ...prev, selectedTags: newTags };
    });
  };

  const clearTags = () => {
    setFilters(prev => ({ ...prev, selectedTags: [] }));
  };

  const scrollToContent = () => {
    contentRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
