import React, { useState, useEffect } from 'react';
import { Course, Organizer } from '../types';
import { REGIONS, DEFAULT_IMAGES } from '../constants';
import { X, Link as LinkIcon, Trash2 } from 'lucide-react';

interface AddCourseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (course: Course) => void;
  onDelete?: (id: string) => void;
  courseToEdit?: Course; // Optional prop for editing
}

export const AddCourseModal: React.FC<AddCourseModalProps> = ({ isOpen, onClose, onSave, onDelete, courseToEdit }) => {
  const [formData, setFormData] = useState<Partial<Course>>({
    organizer: Organizer.KVLO,
    region: 'Landelijk',
    price: 0,
    tags: [],
    url: ''
  });
  const [tagInput, setTagInput] = useState('');

  // Effect to populate form when editing or resetting
  useEffect(() => {
    if (isOpen) {
      if (courseToEdit) {
        setFormData({ ...courseToEdit });
      } else {
        // Reset defaults when adding new, but set DATE to TODAY to prevent immediate filtering
        setFormData({
          organizer: Organizer.KVLO,
          region: 'Landelijk',
          price: 0,
          tags: [],
          url: '',
          date: new Date().toISOString().split('T')[0] // Default to today
        });
      }
    }
  }, [isOpen, courseToEdit]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.date || !formData.description) return;

    // Use existing ID if editing, otherwise generate new
    const id = courseToEdit?.id || Date.now().toString();

    // Preserve existing image if editing and no new one selected (logic simplified as we don't have file upload)
    const imageUrl = formData.imageUrl || (courseToEdit ? courseToEdit.imageUrl : DEFAULT_IMAGES[Math.floor(Math.random() * DEFAULT_IMAGES.length)]);

    const savedCourse: Course = {
      id,
      title: formData.title,
      organizer: formData.organizer as Organizer,
      date: formData.date,
      location: formData.location || 'Onbekend',
      region: formData.region || 'Landelijk',
      price: Number(formData.price) || 0,
      description: formData.description,
      tags: formData.tags || [],
      url: formData.url && formData.url.length > 0 ? formData.url : '#',
      imageUrl,
      isNew: courseToEdit ? courseToEdit.isNew : true // Keep existing status if editing
    };

    onSave(savedCourse);
    onClose();
  };

  const handleAddTag = () => {
    if (tagInput.trim()) {
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), tagInput.trim()]
      }));
      setTagInput('');
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-[#1e293b]/80 backdrop-blur-sm transition-opacity">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto transform transition-all">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center sticky top-0 bg-white z-10">
          <div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tight">
                {courseToEdit ? 'Scholing Bewerken' : 'Nieuwe Scholing'}
              </h2>
              <p className="text-sm text-slate-500 font-medium">
                {courseToEdit ? 'Pas de gegevens van deze cursus aan' : 'Voeg een cursus toe aan de kalender'}
              </p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-50 rounded-full transition-colors">
            <X className="w-6 h-6 text-slate-400 hover:text-red-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2 col-span-1 md:col-span-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Titel</label>
              <input 
                required
                type="text" 
                className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] focus:border-transparent outline-none transition-shadow"
                value={formData.title || ''}
                onChange={e => setFormData({...formData, title: e.target.value})}
                placeholder="Bijv: Workshop Freerunning Basis"
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Organisator</label>
              <select 
                className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow bg-white"
                value={formData.organizer}
                onChange={e => setFormData({...formData, organizer: e.target.value as Organizer})}
              >
                {Object.values(Organizer).map(org => (
                  <option key={org} value={org}>{org}</option>
                ))}
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Datum</label>
              <input 
                required
                type="date" 
                className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                value={formData.date || ''}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Locatie</label>
               <input 
                 type="text"
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 value={formData.location || ''}
                 onChange={e => setFormData({...formData, location: e.target.value})}
                 placeholder="Bijv: Sporthal De Pijp"
               />
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Regio</label>
               <select 
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow bg-white"
                 value={formData.region}
                 onChange={e => setFormData({...formData, region: e.target.value})}
               >
                 {REGIONS.map(r => <option key={r} value={r}>{r}</option>)}
               </select>
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Prijs (€)</label>
               <input 
                 type="number"
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 value={formData.price}
                 onChange={e => setFormData({...formData, price: Number(e.target.value)})}
               />
            </div>

            <div className="space-y-2">
               <label className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-1">
                  Link naar info/aanmelden <LinkIcon className="w-3 h-3" />
               </label>
               <input 
                 type="url"
                 className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 value={formData.url || ''}
                 onChange={e => setFormData({...formData, url: e.target.value})}
                 placeholder="https://www.aanbieder.nl/cursus"
               />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Omschrijving</label>
            <textarea 
              required
              rows={4}
              className="w-full px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none resize-none transition-shadow"
              value={formData.description || ''}
              onChange={e => setFormData({...formData, description: e.target.value})}
              placeholder="Wat gaan de deelnemers leren?"
            />
          </div>

          <div className="space-y-2">
             <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Tags</label>
             <div className="flex gap-2">
               <input 
                 type="text" 
                 className="flex-1 px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-[#7AB800] outline-none transition-shadow"
                 placeholder="Bijv: PO, Motorisch Leren..."
                 value={tagInput}
                 onChange={e => setTagInput(e.target.value)}
                 onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), handleAddTag())}
               />
               <button 
                 type="button" 
                 onClick={handleAddTag}
                 className="px-4 py-2.5 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors font-bold"
               >
                 +
               </button>
             </div>
             <div className="flex flex-wrap gap-2 mt-2">
               {formData.tags?.map(tag => (
                 <span key={tag} className="bg-[#E0F7FA] text-[#006064] px-2.5 py-1 rounded-md text-xs font-bold flex items-center gap-1 border border-[#B2EBF2]">
                   {tag}
                   <button 
                     type="button"
                     onClick={() => setFormData({...formData, tags: formData.tags?.filter(t => t !== tag)})}
                     className="hover:text-red-500"
                   >
                     ×
                   </button>
                 </span>
               ))}
             </div>
          </div>

          <div className="pt-6 flex justify-between border-t border-slate-50">
             {courseToEdit && onDelete && (
                <button 
                    type="button"
                    onClick={() => onDelete(courseToEdit.id)}
                    className="px-4 py-2.5 text-red-500 font-bold hover:bg-red-50 rounded-lg transition-colors flex items-center gap-2"
                >
                    <Trash2 className="w-4 h-4" />
                    <span className="hidden sm:inline">Verwijderen</span>
                </button>
             )}

             <div className="flex gap-3 ml-auto">
                <button 
                type="button" 
                onClick={onClose}
                className="px-6 py-2.5 text-slate-500 font-bold hover:bg-slate-50 rounded-lg transition-colors"
                >
                Annuleren
                </button>
                <button 
                type="submit"
                className="px-8 py-2.5 bg-gradient-to-r from-[#7AB800] to-[#6da500] text-white font-bold rounded-lg hover:shadow-lg hover:shadow-green-500/30 transition-all transform hover:-translate-y-0.5"
                >
                {courseToEdit ? 'Opslaan' : 'Toevoegen'}
                </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

