import { initializeApp } from 'firebase/app';
import { getFirestore, collection, doc, setDoc, deleteDoc, onSnapshot, query, orderBy } from 'firebase/firestore';
import { Course } from '../types';
import { INITIAL_COURSES } from '../constants';

// ------------------------------------------------------------------
// CONFIGURATIE: MULTI-USER DATABASE
// ------------------------------------------------------------------
// Om de app te laten werken op meerdere apparaten tegelijk, moet je
// hieronder de gegevens van je eigen Firebase project invullen.
// Ga naar https://console.firebase.google.com/, maak een project,
// en kies "Add app" -> "Web". Kopieer de config hierheen.
// ------------------------------------------------------------------

const firebaseConfig = {
  apiKey: "VUL_HIER_JE_API_KEY", // Vervang dit met je echte API Key
  authDomain: "jouw-project.firebaseapp.com",
  projectId: "jouw-project-id",
  storageBucket: "jouw-project.appspot.com",
  messagingSenderId: "123456789",
  appId: "1:123456789:web:abcdef"
};

// Interne logica om te bepalen of we Live zijn of in Demo modus
let db: any = null;
const isConfigured = firebaseConfig.apiKey !== "VUL_HIER_JE_API_KEY";

if (isConfigured) {
  try {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    console.log("✅ Verbonden met Firebase Database");
  } catch (e) {
    console.error("❌ Firebase connectie fout:", e);
  }
} else {
  console.log("⚠️ Geen Firebase config gevonden. App draait in lokale demo-modus.");
}

// Custom event voor lokale updates zodat de UI reageert zonder database
const LOCAL_EVENT = 'local-storage-update';

// Functie om naar updates te luisteren (Real-time!)
export const subscribeToCourses = (onUpdate: (courses: Course[]) => void) => {
  if (isConfigured && db) {
    // LIVE MODUS: Luister naar Firestore
    const q = query(collection(db, "courses"));
    return onSnapshot(q, (snapshot) => {
      const courses = snapshot.docs.map(doc => doc.data() as Course);
      onUpdate(courses);
    }, (error) => {
      console.error("Fout bij ophalen data:", error);
    });
  } else {
    // DEMO MODUS: Luister naar LocalStorage events
    const loadLocal = () => {
      const saved = localStorage.getItem('local_courses');
      const courses = saved ? JSON.parse(saved) : INITIAL_COURSES;
      onUpdate(courses);
    };

    loadLocal(); // Direct laden

    const handleStorageEvent = () => loadLocal();
    window.addEventListener(LOCAL_EVENT, handleStorageEvent);
    // Luister ook naar storage events van andere tabbladen
    window.addEventListener('storage', handleStorageEvent);

    return () => {
      window.removeEventListener(LOCAL_EVENT, handleStorageEvent);
      window.removeEventListener('storage', handleStorageEvent);
    };
  }
};

// Scholing opslaan (Toevoegen of Bewerken)
export const saveCourseToDB = async (course: Course) => {
  if (isConfigured && db) {
    // LIVE MODUS
    await setDoc(doc(db, "courses", course.id), course);
  } else {
    // DEMO MODUS
    const saved = localStorage.getItem('local_courses');
    const current = saved ? JSON.parse(saved) : INITIAL_COURSES;

    const exists = current.some((c: Course) => c.id === course.id);
    let next;

    if (exists) {
      next = current.map((c: Course) => c.id === course.id ? course : c);
    } else {
      next = [course, ...current];
    }

    localStorage.setItem('local_courses', JSON.stringify(next));
    window.dispatchEvent(new Event(LOCAL_EVENT));
  }
};

// Scholing verwijderen
export const deleteCourseFromDB = async (id: string) => {
  if (isConfigured && db) {
    // LIVE MODUS
    await deleteDoc(doc(db, "courses", id));
  } else {
    // DEMO MODUS
    const saved = localStorage.getItem('local_courses');
    const current = saved ? JSON.parse(saved) : INITIAL_COURSES;
    const next = current.filter((c: Course) => c.id !== id);

    localStorage.setItem('local_courses', JSON.stringify(next));
    window.dispatchEvent(new Event(LOCAL_EVENT));
  }
};

export const isLiveMode = () => isConfigured;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { CourseCard } from './components/CourseCard';
import { AddCourseModal } from './components/AddCourseModal';
import { CourseDetailModal } from './components/CourseDetailModal';
import { AIAssistant } from './components/AIAssistant';
import { Toast } from './components/Toast';
import { CalendarView } from './components/CalendarView';
import { MapView } from './components/MapView';
import { AdminLoginModal } from './components/AdminLoginModal';
import { Course, SearchFilters, SortOption } from './types';
import { REGIONS } from './constants';
import { subscribeToCourses, saveCourseToDB, deleteCourseFromDB, isLiveMode } from './services/db';
import { Search, ChevronDown, Plus, Heart, SlidersHorizontal, LayoutGrid, Calendar as CalendarIcon, Map as MapIcon, ShieldCheck, Wifi, WifiOff } from 'lucide-react';

type ViewMode = 'list' | 'calendar' | 'map';

const App: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [favorites, setFavorites] = useState<string[]>(() => {
    const saved = localStorage.getItem('alo_kvlo_favorites');
    return saved ? JSON.parse(saved) : [];
  });

  const [filters, setFilters] = useState<SearchFilters>({
    query: '',
    region: 'Alle',
    dateStart: '',
    dateEnd: '',
    organizer: 'Alle',
    selectedTags: []
  });

  const [sortOption, setSortOption] = useState<SortOption>('date-asc');
  const [showOnlyFavorites, setShowOnlyFavorites] = useState(false);
  const [showMobileFilters, setShowMobileFilters] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [courseToEdit, setCourseToEdit] = useState<Course | undefined>(undefined);
  const [toast, setToast] = useState<{message: string, isVisible: boolean}>({ message: '', isVisible: false });
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const contentRef = useRef<HTMLDivElement>(null);

  // Subscribe to DB updates
  useEffect(() => {
    setIsLoading(true);
    const unsubscribe = subscribeToCourses((newCourses) => {
      setCourses(newCourses);
      setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    localStorage.setItem('alo_kvlo_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const toggleFavorite = (id: string) => {
    setFavorites(prev => 
      prev.includes(id) ? prev.filter(fav => fav !== id) : [...prev, id]
    );
  };

  const showToast = (message: string) => {
    setToast({ message, isVisible: true });
  };

  const handleAdminToggle = () => {
    if (isAdmin) {
      setIsAdmin(false);
      showToast("Beheerdersmodus uitgeschakeld");
    } else {
      setShowAdminLogin(true);
    }
  };

  const handleLoginSuccess = () => {
    setIsAdmin(true);
    setShowAdminLogin(false);
    showToast("Beheerdersmodus geactiveerd");
  };

  const filteredAndSortedCourses = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];

    let result = courses.filter(course => {
      // Verberg verlopen scholingen tenzij in beheer-modus
      if (course.date < todayStr && !isAdmin) return false;

      const matchesQuery = 
        course.title.toLowerCase().includes(filters.query.toLowerCase()) || 
        course.description.toLowerCase().includes(filters.query.toLowerCase()) ||
        course.tags.some(tag => tag.toLowerCase().includes(filters.query.toLowerCase()));

      const matchesRegion = filters.region === 'Alle' || course.region === filters.region;
      const matchesDateStart = !filters.dateStart || course.date >= filters.dateStart;
      const matchesDateEnd = !filters.dateEnd || course.date <= filters.dateEnd;
      const matchesOrganizer = filters.organizer === 'Alle' || course.organizer === filters.organizer;
      const matchesTags = filters.selectedTags.length === 0 || 
        filters.selectedTags.some(tag => course.tags.includes(tag));
      const matchesFavorite = !showOnlyFavorites || favorites.includes(course.id);

      return matchesQuery && matchesRegion && matchesDateStart && matchesDateEnd && matchesOrganizer && matchesTags && matchesFavorite;
    });

    result.sort((a, b) => {
      if (sortOption === 'date-asc') return a.date.localeCompare(b.date);
      if (sortOption === 'date-desc') return b.date.localeCompare(a.date);
      if (sortOption === 'price-asc') return a.price - b.price;
      if (sortOption === 'price-desc') return b.price - a.price;
      return 0;
    });

    return result;
  }, [courses, filters, favorites, showOnlyFavorites, sortOption, isAdmin]);

  const handleSaveCourse = async (savedCourse: Course) => {
    try {
      await saveCourseToDB(savedCourse);
      showToast(courseToEdit ? "Scholing bijgewerkt" : "Scholing toegevoegd");
