      <Hero courseCount={courses.length} onScrollToContent={() => contentRef.current?.scrollIntoView({ behavior: 'smooth' })} />

      <main ref={contentRef} className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-32 md:pb-16">

