        </div>

        {/* Search & Filter Bar */}
        <div className={`bg-white p-6 rounded-2xl shadow-sm border border-slate-100 mb-10 md:-mt-12 relative z-20 transition-all ${showMobileFilters ? 'block' : 'hidden md:block'}`}>
