import React, { useState, useRef, useEffect } from 'react';
import { Course, ChatMessage } from '../types';
import { getSmartRecommendations } from '../services/geminiService';
import { Sparkles, Send, X, Bot, Lock } from 'lucide-react';

interface AIAssistantProps {
  courses: Course[];
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ courses }) => {
  const [isOpen, setIsOpen] = useState(false);

  // Check veilig of de key er is (via de define in vite.config.ts)
  const hasApiKey = typeof process !== 'undefined' && process.env && process.env.API_KEY && process.env.API_KEY !== "undefined" && process.env.API_KEY !== "";

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  // Initialize welcome message based on config status
  useEffect(() => {
    if (messages.length === 0) {
      if (hasApiKey) {
        setMessages([{ role: 'model', text: 'Hoi! Ik ben de slimme assistent van LO Academie. Waar ben je naar op zoek?' }]);
      } else {
        setMessages([{ 
          role: 'model', 
          text: '⚠️ Configuratie vereist: De slimme zoekhulp is nog niet actief. Maak een .env bestand aan in de root van je project en voeg de regel "API_KEY=jouw-sleutel" toe om te starten.' 
        }]);
      }
    }
  }, [hasApiKey, messages.length]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [messages, isOpen]);

  // Handle click outside to close
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (chatContainerRef.current && !chatContainerRef.current.contains(event.target as Node) && isOpen) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [isOpen]);

  const handleSend = async () => {
    if (!input.trim() || loading || !hasApiKey) return;

    const userText = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userText }]);
    setLoading(true);

    const response = await getSmartRecommendations(userText, courses);

    setMessages(prev => [...prev, { role: 'model', text: response }]);
    setLoading(false);
  };

  return (
    <div ref={chatContainerRef}>
      {/* Floating Action Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-6 right-6 z-40 p-4 rounded-full shadow-xl shadow-[#00C1D4]/20 transition-all duration-300 flex items-center gap-2
          ${isOpen ? 'scale-0 opacity-0' : 'scale-100 opacity-100'}
          ${hasApiKey ? 'bg-gradient-to-r from-[#00C1D4] to-[#0096a6] hover:scale-110' : 'bg-slate-400 hover:bg-slate-500'} text-white`}
      >
        {hasApiKey ? <Sparkles className="w-6 h-6" /> : <Lock className="w-6 h-6" />}
        <span className="font-bold hidden md:inline">Slimme Zoekhulp</span>
      </button>

      {/* Chat Interface */}
      <div className={`fixed bottom-6 right-6 z-50 w-full md:w-[400px] h-[500px] bg-white rounded-2xl shadow-2xl border border-slate-200 flex flex-col transition-all duration-300 transform origin-bottom-right
        ${isOpen ? 'scale-100 opacity-100' : 'scale-0 opacity-0 pointer-events-none translate-y-10'}`}>

        {/* Chat Header */}
        <div className={`p-4 rounded-t-2xl flex justify-between items-center text-white
          ${hasApiKey ? 'bg-gradient-to-r from-[#7AB800] to-[#00C1D4]' : 'bg-slate-600'}`}>
          <div className="flex items-center gap-2">
            <Bot className="w-6 h-6" />
            <h3 className="font-bold text-lg">LO Assistent {hasApiKey ? '' : '(Offline)'}</h3>
          </div>
          <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1 rounded-full transition-colors cursor-pointer">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] p-3.5 rounded-2xl text-sm leading-relaxed shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-[#00C1D4] text-white rounded-tr-none' 
                  : 'bg-white border border-slate-100 text-slate-700 rounded-tl-none'
              }`}>
                {msg.text}
              </div>
            </div>
          ))}
          {loading && (
             <div className="flex justify-start">
               <div className="bg-white border border-slate-100 p-4 rounded-2xl rounded-tl-none shadow-sm flex gap-1.5">
                 <div className="w-2 h-2 bg-[#7AB800] rounded-full animate-bounce"></div>
                 <div className="w-2 h-2 bg-[#7AB800] rounded-full animate-bounce delay-75"></div>
                 <div className="w-2 h-2 bg-[#7AB800] rounded-full animate-bounce delay-150"></div>
               </div>
             </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="p-4 bg-white border-t border-slate-100">
          <div className="flex gap-2">
            <input 
              type="text" 
              className="flex-1 px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#7AB800] text-sm disabled:bg-slate-100 disabled:text-slate-400"
              placeholder={hasApiKey ? "Typ je vraag..." : "API Key ontbreekt in configuratie"}
              value={input}
              disabled={!hasApiKey || loading}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
            />
            <button 
              onClick={handleSend}
              disabled={loading || !input.trim() || !hasApiKey}
              className="p-3 bg-[#7AB800] text-white rounded-xl hover:bg-[#6da500] disabled:opacity-50 disabled:bg-slate-300 transition-colors shadow-sm cursor-pointer"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Course } from '../types';

// We initialiseren de client NIET hier, maar pas in de functie. 
// Dit voorkomt dat de app crasht bij het laden (White Screen) als de API Key mist of de env nog niet geladen is.

export const getSmartRecommendations = async (userQuery: string, availableCourses: Course[]): Promise<string> => {
  try {
    // Haal API key op. We ondersteunen zowel Vite's import.meta.env als process.env
    const apiKey = process.env.API_KEY;

    if (!apiKey || apiKey === "undefined" || apiKey === "") {
        console.warn("Gemini API Key ontbreekt in environment variables.");
        return "Ik kan helaas geen slimme aanbevelingen doen omdat mijn AI-sleutel ontbreekt. De beheerder moet de API_KEY instellen in de configuratie.";
    }

    // Lazy initialization met de key
    const ai = new GoogleGenAI({ apiKey: apiKey });

    const courseContext = JSON.stringify(availableCourses.map(c => ({
      id: c.id,
      title: c.title,
      date: c.date,
      organizer: c.organizer,
      region: c.region,
      description: c.description,
      tags: c.tags
    })));

    const prompt = `
      Je bent de 'LO Academie Assistent', de slimme gids voor de scholingskalender van KVLO en ALO Nederland.

      Jouw doelen:
      1. Help docenten de juiste bijscholing te vinden.
      2. Geef context over vaktermen (bijv. MRT, BSM, bewegend leren) als daarom gevraagd wordt, gebruik hiervoor Google Search.
      3. Wees enthousiast over het vak bewegingsonderwijs.

      Hier is de lijst met ACTUELE cursussen in onze database (JSON):
      ${courseContext}

      De gebruiker vraagt: "${userQuery}"

      Richtlijnen voor je antwoord:
      - **GEBRUIK OPMAAK:** Maak je antwoord visueel aantrekkelijk.
      - Gebruik **dikgedrukte tekst** voor namen van cursussen, datums en belangrijke begrippen.
      - Gebruik lijstjes (bulletpoints) als je meerdere opties noemt.
      - Gebruik kopjes (### Koptekst) om structuur aan te brengen als het antwoord lang is.
      - Als de gebruiker zoekt naar een cursus: Zoek in de JSON en beveel 1-3 opties aan. Noem titel, datum en locatie.
      - Als de gebruiker een algemene vraag stelt (bijv. "Wat is BSM?"): Gebruik Google Search om een korte, correcte definitie te geven en kijk DAN of er cursussen over zijn.
      - Als er geen cursus gevonden is: Zeg dit eerlijk, maar bied aan om algemene info over het onderwerp te zoeken of stel een alternatief voor.
      - Spreek de gebruiker aan met "je/jij".
      - Houd het beknopt (max 150 woorden).

      Antwoord nu:
    `;

    // Gebruik de 'gemini-3-flash-preview' model zoals voorgeschreven voor basistaken met grounding
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }] // Enable Grounding with Google Search
      }
    });

    let text = response.text || "Sorry, ik kon op dit moment geen antwoord genereren. Probeer het later opnieuw.";

    // Check for grounding metadata to display sources
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      const uniqueLinks = new Set<string>();
      chunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          uniqueLinks.add(chunk.web.uri);
        }
      });

      if (uniqueLinks.size > 0) {
        text += "\n\n### Bronnen\n";
        Array.from(uniqueLinks).forEach((link, index) => {
           text += `- [Bron ${index + 1}](${link})\n`;
        });
      }
    }

    return text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Er is een fout opgetreden bij het ophalen van slimme aanbevelingen. Controleer je internetverbinding of probeer de gewone zoekfilters.";
  }
};

