        <div className="absolute inset-0 bg-slate-900/50 backdrop-blur-sm" onClick={closeMobile} />
        <div className="absolute right-0 top-0 bottom-0 w-[85%] max-w-sm bg-white shadow-2xl p-6 overflow-y-auto">
