                    <button onClick={openAddModal} className="text-xs font-bold text-[#7AB800] hover:underline flex items-center gap-1">
                        <Plus className="w-3 h-3" /> Toevoegen
                    </button>
                  </div>
               ) : (
                  // DB Status for non-admins
                  <div className="flex items-center">
                    {!isLiveMode() ? (
