        <div className={`absolute right-0 top-0 bottom-0 w-[85%] max-w-sm bg-white shadow-2xl p-6 overflow-y-auto transition-transform duration-300 ${isOpenMobile ? 'translate-x-0' : 'translate-x-full'}`}>
